COMPANIONS[(1, 2)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Prevodník megabajtov na jednotky', 'title_en': 'Exercise 2 (Medium): Megabyte Unit Converter', 'instructions_sk': 'Napíš funkciu `prevod_jednotiek_pamate(megabajty)`: vráti trojicu `(kilobajty, bajty, bity)`. $1\\text{ MB} = 1024\\text{ KB}$, $1\\text{ KB} = 1024\\text{ B}$, $1\\text{ B} = 8\\text{ bitov}$.', 'instructions_en': 'Write `prevod_jednotiek_pamate(megabajty)` returning tuple (kb, bytes, bits).', 'starter_code': 'def prevod_jednotiek_pamate(megabajty):\n    pass\n', 'solution_code': 'def prevod_jednotiek_pamate(megabajty):\n    kb = megabajty * 1024\n    b = kb * 1024\n    bity = b * 8\n    return (kb, b, bity)\n', 'explanation_sk': 'Aritmetické výpočty s binárnymi jednotkami informácie.', 'explanation_en': 'Binary memory unit conversion arithmetic.', 'hint_sk': 'kb = megabajty * 1024; b = kb * 1024; bity = b * 8; return (kb, b, bity)', 'hint_en': 'Calculate kb, bytes, and bits iteratively.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'prevod_jednotiek_pamate(1)', 'expected_output': '(1024, 1048576, 8388608)', 'test_code': 'assert prevod_jednotiek_pamate(1) == (1024, 1048576, 8388608)', 'is_hidden': False}, {'input_data': 'prevod_jednotiek_pamate(2)', 'expected_output': '(2048, 2097152, 16777216)', 'test_code': 'assert prevod_jednotiek_pamate(2) == (2048, 2097152, 16777216)', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Kalkulačka BMI indexu a klasifikácia', 'title_en': 'Exercise 3 (Boss Challenge): BMI Index and Classification', 'instructions_sk': 'Napíš funkciu `vypocitaj_bmi(vaha_kg, vyska_cm)`: vráti dvojicu `(zaokruhlene_bmi_na_1_des_miesto, kategoria)`. $BMI = \\frac{vaha}{(vyska / 100)^2}$. Kategórie: <18.5 "Podváha", <25.0 "Normálna váha", <30.0 "Nadváha", inak "Obezita".', 'instructions_en': 'Write `vypocitaj_bmi(vaha_kg, vyska_cm)` returning (bmi_float_1_dec, category_str).', 'starter_code': 'def vypocitaj_bmi(vaha_kg, vyska_cm):\n    pass\n', 'solution_code': 'def vypocitaj_bmi(vaha_kg, vyska_cm):\n    vyska_m = vyska_cm / 100.0\n    bmi = round(vaha_kg / (vyska_m ** 2), 1)\n    if bmi < 18.5:\n        kat = "Podváha"\n    elif bmi < 25.0:\n        kat = "Normálna váha"\n    elif bmi < 30.0:\n        kat = "Nadváha"\n    else:\n        kat = "Obezita"\n    return (bmi, kat)\n', 'explanation_sk': 'Výpočet BMI indexu s viacstupňovým vetvením a zaokrúhľovaním.', 'explanation_en': 'BMI formula calculation with classification boundaries.', 'hint_sk': 'vyska_m = vyska_cm / 100; bmi = round(vaha_kg / (vyska_m ** 2), 1)', 'hint_en': 'Convert cm to m and compute BMI.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'vypocitaj_bmi(70, 175)', 'expected_output': '(22.9, "Normálna váha")', 'test_code': 'assert vypocitaj_bmi(70, 175) == (22.9, "Normálna váha")', 'is_hidden': False}, {'input_data': 'vypocitaj_bmi(50, 175)', 'expected_output': '(16.3, "Podváha")', 'test_code': 'assert vypocitaj_bmi(50, 175) == (16.3, "Podváha")', 'is_hidden': True}]}]

