COMPANIONS[(1, 3)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Rozpoznanie základného dátového typu', 'title_en': 'Exercise 1 (Easy): Basic Data Type Identification', 'instructions_sk': 'Napíš funkciu `zisti_typ(hodnota)`: vráti "BOOL" ak je bool, "INT" ak int, "FLOAT" ak float, "STR" ak str, inak "OTHER".', 'instructions_en': 'Write `zisti_typ(hodnota)` returning "INT", "FLOAT", "STR", "BOOL" or "OTHER".', 'starter_code': 'def zisti_typ(hodnota):\n    pass\n', 'solution_code': 'def zisti_typ(hodnota):\n    if type(hodnota) is bool:\n        return "BOOL"\n    elif type(hodnota) is int:\n        return "INT"\n    elif type(hodnota) is float:\n        return "FLOAT"\n    elif type(hodnota) is str:\n        return "STR"\n    return "OTHER"\n', 'explanation_sk': 'Použitie type() is bool pred type() is int.', 'explanation_en': 'Using type() equality check handling bool vs int inheritance in Python.', 'hint_sk': 'Použi type(hodnota) is bool ako prvé!', 'hint_en': 'Check type(hodnota) is bool first.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'zisti_typ(42)', 'expected_output': 'INT', 'test_code': 'assert zisti_typ(42) == "INT"', 'is_hidden': False}, {'input_data': 'zisti_typ(True)', 'expected_output': 'BOOL', 'test_code': 'assert zisti_typ(True) == "BOOL"', 'is_hidden': False}, {'input_data': 'zisti_typ(3.14)', 'expected_output': 'FLOAT', 'test_code': 'assert zisti_typ(3.14) == "FLOAT"', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Sčítanie čísel v zozname s vynechaním booleanov', 'title_en': 'Exercise 3 (Boss Challenge): Sum Numbers Excluding Bools', 'instructions_sk': 'Napíš funkciu `spocitaj_cisla_v_zozname(zoznam)`: prejde zoznam a vráti súčet prvkov typu int a float (nie bool). Zaokrúhli na 2 desatinné miesta.', 'instructions_en': 'Write `spocitaj_cisla_v_zozname(zoznam)` summing ints and floats excluding bools.', 'starter_code': 'def spocitaj_cisla_v_zozname(zoznam):\n    pass\n', 'solution_code': 'def spocitaj_cisla_v_zozname(zoznam):\n    spolu = 0.0\n    for x in zoznam:\n        if type(x) in (int, float):\n            spolu += x\n    return round(spolu, 2)\n', 'explanation_sk': 'Filtrovanie prvkov cez type(x) in (int, float).', 'explanation_en': 'Type checking filtering out boolean values while aggregating numeric primitives.', 'hint_sk': 'if type(x) in (int, float): spolu += x', 'hint_en': 'Check type(x) in (int, float).', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'spocitaj_cisla_v_zozname([10, "text", True, 2.5, False, 5])', 'expected_output': '17.5', 'test_code': 'assert spocitaj_cisla_v_zozname([10, "text", True, 2.5, False, 5]) == 17.5', 'is_hidden': False}, {'input_data': 'spocitaj_cisla_v_zozname([True, False, "100"])', 'expected_output': '0.0', 'test_code': 'assert spocitaj_cisla_v_zozname([True, False, "100"]) == 0.0', 'is_hidden': True}]}]

