COMPANIONS[(1, 4)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Prevod textových hodnôt na čísla', 'title_en': 'Exercise 2 (Medium): Parse Strings to Numbers', 'instructions_sk': 'Napíš funkciu `parsuj_cisla(retezce)`: vráti nový zoznam úspešne skonvertovaných čísel int a float. Neplatné reťazce preskočí.', 'instructions_en': 'Write `parsuj_cisla(retezce)` parsing valid int and float values from strings.', 'starter_code': 'def parsuj_cisla(retezce):\n    pass\n', 'solution_code': 'def parsuj_cisla(retezce):\n    vysledok = []\n    for s in retezce:\n        try:\n            if "." in s:\n                vysledok.append(float(s))\n            else:\n                vysledok.append(int(s))\n        except ValueError:\n            continue\n    return vysledok\n', 'explanation_sk': 'Defenzívne pretypovanie pomocou try-except ValueError.', 'explanation_en': 'Defensive type casting catching ValueError.', 'hint_sk': 'Použi try: if "." in s: float(s) else: int(s) except ValueError: pass', 'hint_en': 'Use try-except ValueError.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'parsuj_cisla(["10", "ahoj", "2.5", "100", "xyz"])', 'expected_output': '[10, 2.5, 100]', 'test_code': 'assert parsuj_cisla(["10", "ahoj", "2.5", "100", "xyz"]) == [10, 2.5, 100]', 'is_hidden': False}, {'input_data': 'parsuj_cisla(["bad", "data"])', 'expected_output': '[]', 'test_code': 'assert parsuj_cisla(["bad", "data"]) == []', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Univerzálny pretypovač hodnôt', 'title_en': 'Exercise 3 (Boss Challenge): Universal Type Converter', 'instructions_sk': 'Napíš funkciu `konvertuj_hodnotu(hodnota, cielovy_typ)`: podporuje "int", "float", "str", "bool". Ak zlyhá, vráti None.', 'instructions_en': 'Write `konvertuj_hodnotu(hodnota, cielovy_typ)` safely converting to target type or returning None.', 'starter_code': 'def konvertuj_hodnotu(hodnota, cielovy_typ):\n    pass\n', 'solution_code': 'def konvertuj_hodnotu(hodnota, cielovy_typ):\n    try:\n        if cielovy_typ == "int":\n            return int(float(hodnota))\n        elif cielovy_typ == "float":\n            return float(hodnota)\n        elif cielovy_typ == "str":\n            return str(hodnota)\n        elif cielovy_typ == "bool":\n            if isinstance(hodnota, str):\n                return hodnota.strip().lower() in ("true", "1", "ano", "yes")\n            return bool(hodnota)\n        return None\n    except (ValueError, TypeError):\n        return None\n', 'explanation_sk': 'Komplexná konverzia s ošetrením chýb.', 'explanation_en': 'Robust type casting handling conversions errors.', 'hint_sk': 'try: if cielovy_typ == "int": return int(float(hodnota)) ... except: return None', 'hint_en': 'Wrap target conversions in try-except.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'konvertuj_hodnotu("12.5", "int")', 'expected_output': '12', 'test_code': 'assert konvertuj_hodnotu("12.5", "int") == 12', 'is_hidden': False}, {'input_data': 'konvertuj_hodnotu("ano", "bool")', 'expected_output': 'True', 'test_code': 'assert konvertuj_hodnotu("ano", "bool") is True', 'is_hidden': False}, {'input_data': 'konvertuj_hodnotu("neplatne", "float")', 'expected_output': 'None', 'test_code': 'assert konvertuj_hodnotu("neplatne", "float") is None', 'is_hidden': True}]}]

