COMPANIONS[(2, 2)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Test priestupného roka', 'title_en': 'Exercise 2 (Medium): Leap Year Calculator', 'instructions_sk': 'Napíš funkciu `je_priestupny(rok)`: vráti `True`, ak je rok priestupný (deliteľný 4 a nie 100, alebo deliteľný 400), inak `False`.', 'instructions_en': 'Write `je_priestupny(rok)` returning True if leap year else False.', 'starter_code': 'def je_priestupny(rok):\n    pass\n', 'solution_code': 'def je_priestupny(rok):\n    return (rok % 4 == 0 and rok % 100 != 0) or (rok % 400 == 0)\n', 'explanation_sk': 'Zložená logická podmienka s operátormi and a or.', 'explanation_en': 'Compound boolean expression handling leap year calendar rules.', 'hint_sk': '(rok % 4 == 0 and rok % 100 != 0) or (rok % 400 == 0)', 'hint_en': 'Combine modulo checks with and/or.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'je_priestupny(2024)', 'expected_output': 'True', 'test_code': 'assert je_priestupny(2024) is True', 'is_hidden': False}, {'input_data': 'je_priestupny(1900)', 'expected_output': 'False', 'test_code': 'assert je_priestupny(1900) is False', 'is_hidden': False}, {'input_data': 'je_priestupny(2000)', 'expected_output': 'True', 'test_code': 'assert je_priestupny(2000) is True', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Validátor IPv4 adries', 'title_en': 'Exercise 3 (Boss Challenge): IPv4 Address Validator', 'instructions_sk': 'Napíš funkciu `validuj_ipv4(ip_adresa)`: vráti `True`, ak reťazec pozostáva presne zo 4 celočíselných oktetov oddelených bodkou, pričom každý oktet je v rozsahu 0 až 255 (bez prázdnych znakov). Inak `False`.', 'instructions_en': 'Write `validuj_ipv4(ip_adresa)` validating IPv4 format and octet ranges 0-255.', 'starter_code': 'def validuj_ipv4(ip_adresa):\n    pass\n', 'solution_code': 'def validuj_ipv4(ip_adresa):\n    casti = ip_adresa.split(".")\n    if len(casti) != 4:\n        return False\n    for c in casti:\n        if not c.isdigit():\n            return False\n        val = int(c)\n        if not (0 <= val <= 255):\n            return False\n        if len(c) > 1 and c[0] == "0":\n            return False\n    return True\n', 'explanation_sk': 'Parsovanie bodiek a kontrola rozsahu každého čísla 0-255.', 'explanation_en': 'String splitting validating octet count and value limits.', 'hint_sk': 'casti = ip_adresa.split("."); len(casti) == 4 and all(c.isdigit() and 0 <= int(c) <= 255 for c in casti)', 'hint_en': 'Check split length and octet range.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'validuj_ipv4("192.168.1.1")', 'expected_output': 'True', 'test_code': 'assert validuj_ipv4("192.168.1.1") is True', 'is_hidden': False}, {'input_data': 'validuj_ipv4("256.100.0.1")', 'expected_output': 'False', 'test_code': 'assert validuj_ipv4("256.100.0.1") is False', 'is_hidden': False}, {'input_data': 'validuj_ipv4("10.0.1")', 'expected_output': 'False', 'test_code': 'assert validuj_ipv4("10.0.1") is False', 'is_hidden': True}]}]

