COMPANIONS[(2, 3)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Reverzia a skrátenie reťazca', 'title_en': 'Exercise 2 (Medium): Reverse and Truncate String', 'instructions_sk': 'Napíš funkciu `otoc_a_skrat(text, max_dlzka=10)`: otočí reťazec odzadu. Ak je jeho dĺžka väčšia ako `max_dlzka`, oreže ho na `max_dlzka` znakov a pridá `"..."`.', 'instructions_en': 'Write `otoc_a_skrat(text, max_dlzka=10)` reversing string and truncating with ellipsis.', 'starter_code': 'def otoc_a_skrat(text, max_dlzka=10):\n    pass\n', 'solution_code': 'def otoc_a_skrat(text, max_dlzka=10):\n    otoceny = text[::-1]\n    if len(otoceny) > max_dlzka:\n        return otoceny[:max_dlzka] + "..."\n    return otoceny\n', 'explanation_sk': 'Reverzovanie cez slicing [::-1] a podmienené orezanie [:max_dlzka].', 'explanation_en': 'String slicing for reversal and boundary truncation.', 'hint_sk': 'otoceny = text[::-1]; if len(otoceny) > max_dlzka: return otoceny[:max_dlzka] + "..."', 'hint_en': 'Use [::-1] and [:max_dlzka].', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'otoc_a_skrat("Programovanie", max_dlzka=7)', 'expected_output': 'einavom...', 'test_code': 'assert otoc_a_skrat("Programovanie", max_dlzka=7) == "einavom..."', 'is_hidden': False}, {'input_data': 'otoc_a_skrat("Ahoj", max_dlzka=10)', 'expected_output': 'johA', 'test_code': 'assert otoc_a_skrat("Ahoj", max_dlzka=10) == "johA"', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Cyklická rotácia reťazca', 'title_en': 'Exercise 3 (Boss Challenge): Cyclic String Shift', 'instructions_sk': 'Napíš funkciu `rotuj_retazec(text, k)`: posunie znaky v reťazci cyklicky doprava o `k` pozícií. Pre prázdny reťazec vráti `""`. Napr. `"abcdef"` o 2 dá `"efabcd"`.', 'instructions_en': 'Write `rotuj_retazec(text, k)` cyclically shifting characters to the right by k.', 'starter_code': 'def rotuj_retazec(text, k):\n    pass\n', 'solution_code': 'def rotuj_retazec(text, k):\n    if not text:\n        return ""\n    k = k % len(text)\n    return text[-k:] + text[:-k] if k != 0 else text\n', 'explanation_sk': 'Modulo dĺžky a spájanie odrezkov textu text[-k:] + text[:-k].', 'explanation_en': 'Modulo offset slicing text[-k:] and text[:-k].', 'hint_sk': 'k = k % len(text); return text[-k:] + text[:-k]', 'hint_en': 'Modulo k with length and slice.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'rotuj_retazec("abcdef", 2)', 'expected_output': 'efabcd', 'test_code': 'assert rotuj_retazec("abcdef", 2) == "efabcd"', 'is_hidden': False}, {'input_data': 'rotuj_retazec("Codoro", 1)', 'expected_output': 'oCodor', 'test_code': 'assert rotuj_retazec("Codoro", 1) == "oCodor"', 'is_hidden': False}, {'input_data': 'rotuj_retazec("", 5)', 'expected_output': '', 'test_code': 'assert rotuj_retazec("", 5) == ""', 'is_hidden': True}]}]

