COMPANIONS[(2, 4)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Počítadlo samohlások v texte', 'title_en': 'Exercise 2 (Medium): Vowel Counter', 'instructions_sk': 'Napíš funkciu `pocet_samohlasok(text)`: spočíta koľkokrát sa v reťazci nachádzajú samohlásky `a, e, i, o, u` (bez ohľadu na veľkosť písmen).', 'instructions_en': 'Write `pocet_samohlasok(text)` counting vowels a,e,i,o,u case-insensitively.', 'starter_code': 'def pocet_samohlasok(text):\n    pass\n', 'solution_code': 'def pocet_samohlasok(text):\n    samohlasky = set("aeiouAEIOU")\n    return sum(1 for char in text if char in samohlasky)\n', 'explanation_sk': 'Iterácia cez reťazec a overenie príslušnosti k množine samohlások.', 'explanation_en': 'Set membership test counting vowels in string.', 'hint_sk': 'sum(1 for c in text.lower() if c in "aeiou")', 'hint_en': 'Count characters matching "aeiou".', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'pocet_samohlasok("Python Codoro")', 'expected_output': '4', 'test_code': 'assert pocet_samohlasok("Python Codoro") == 4', 'is_hidden': False}, {'input_data': 'pocet_samohlasok("Rytmus")', 'expected_output': '1', 'test_code': 'assert pocet_samohlasok("Rytmus") == 1', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Cenzúrny filter zakázaných slov', 'title_en': 'Exercise 3 (Boss Challenge): Word Blacklist Censor', 'instructions_sk': 'Napíš funkciu `cenzuruj_slova(text, zakazane, nahrada="***")`: nahradí všetky výskyty slov zo zoznamu `zakazane` (bez ohľadu na veľkosť písmen) reťazcom `nahrada`. Vráti očistený text.', 'instructions_en': 'Write `cenzuruj_slova(text, zakazane, nahrada="***")` replacing blacklisted words.', 'starter_code': 'def cenzuruj_slova(text, zakazane, nahrada="***"):\n    pass\n', 'solution_code': 'def cenzuruj_slova(text, zakazane, nahrada="***"):\n    slova = text.split()\n    zakazane_low = {w.lower() for w in zakazane}\n    vysledok = []\n    for slovo in slova:\n        ciste = slovo.strip(".,!?:;")\n        if ciste.lower() in zakazane_low:\n            vysledok.append(nahrada)\n        else:\n            vysledok.append(slovo)\n    return " ".join(vysledok)\n', 'explanation_sk': 'Rozdelenie na slová a porovnanie s množinou zakázaných slov.', 'explanation_en': 'Word splitting matching tokens against lowercased blacklist.', 'hint_sk': 'Rozdeľ na slová, over slovo.lower() v zozname zakázaných a spoj cez " ".join().', 'hint_en': 'Split tokens, check membership, rejoin.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'cenzuruj_slova("Toto je zly a tajny plan", ["zly", "tajny"])', 'expected_output': 'Toto je *** a *** plan', 'test_code': 'assert cenzuruj_slova("Toto je zly a tajny plan", ["zly", "tajny"]) == "Toto je *** a *** plan"', 'is_hidden': False}, {'input_data': 'cenzuruj_slova("Ahoj svet", ["pes"])', 'expected_output': 'Ahoj svet', 'test_code': 'assert cenzuruj_slova("Ahoj svet", ["pes"]) == "Ahoj svet"', 'is_hidden': True}]}]

