COMPANIONS[(2, 5)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Bodkové zarovnanie položky menu', 'title_en': 'Exercise 1 (Easy): Dot-Leader Menu Alignment', 'instructions_sk': 'Napíš funkciu `zarovnaj_cenu(nazov, cena, sirka=20)`: vráti reťazec začínajúci názvom, ukončený cenou formátovanou na 2 desatinné miesta s príponou `" EUR"`, pričom priestor medzi nimi vyplnia bodky `.` tak, aby celková dĺžka bola `sirka`.', 'instructions_en': 'Write `zarovnaj_cenu(nazov, cena, sirka=20)` padding with dots.', 'starter_code': 'def zarovnaj_cenu(nazov, cena, sirka=20):\n    pass\n', 'solution_code': 'def zarovnaj_cenu(nazov, cena, sirka=20):\n    cena_str = f"{cena:.2f} EUR"\n    pocet_bodiek = sirka - len(nazov) - len(cena_str)\n    return f"{nazov}{"." * max(1, pocet_bodiek)}{cena_str}"\n', 'explanation_sk': 'Výpočet dĺžky bodkovej výplne a spojenie textu.', 'explanation_en': 'Calculating dot leader padding length.', 'hint_sk': 'cena_str = f"{cena:.2f} EUR"; bodky = "." * (sirka - len(nazov) - len(cena_str))', 'hint_en': 'Compute dot padding length.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'zarovnaj_cenu("Káva", 2.50, sirka=15)', 'expected_output': 'Káva...2.50 EUR', 'test_code': 'assert zarovnaj_cenu("Káva", 2.50, sirka=15) == "Káva...2.50 EUR"', 'is_hidden': False}, {'input_data': 'zarovnaj_cenu("Čaj", 1.00, sirka=15)', 'expected_output': 'Čaj....1.00 EUR', 'test_code': 'assert zarovnaj_cenu("Čaj", 1.00, sirka=15) == "Čaj....1.00 EUR"', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Formátovač ASCII tabuľky študentov', 'title_en': 'Exercise 3 (Boss Challenge): ASCII Student Table Formatter', 'instructions_sk': 'Napíš funkciu `formatuj_tabulku(hlavicky, riadky)`: `hlavicky` je zoznam 2 názvov stĺpcov, `riadky` je zoznam dvojíc `[(meno, body), ...]`. Funkcia vráti textovú tabuľku, kde každý stĺpec má pevnú šírku 12 znakov oddelenú `" | "`. Medzi hlavičkou a riadkami je deliaca čiara `"-" * 27`.', 'instructions_en': 'Write `formatuj_tabulku(hlavicky, riadky)` formatting 2-column ASCII table.', 'starter_code': 'def formatuj_tabulku(hlavicky, riadky):\n    pass\n', 'solution_code': 'def formatuj_tabulku(hlavicky, riadky):\n    h_str = f"{hlavicky[0]:<12} | {hlavicky[1]:<12}"\n    sep = "-" * 27\n    lines = [h_str, sep]\n    for r1, r2 in riadky:\n        lines.append(f"{str(r1):<12} | {str(r2):<12}")\n    return "\\n".join(lines)\n', 'explanation_sk': 'Zarovnanie stĺpcov doľava pomocou :<12 a zloženie tabuľky.', 'explanation_en': 'Left-aligned column formatting using :<12.', 'hint_sk': 'f"{hlavicky[0]:<12} | {hlavicky[1]:<12}" a spoj riadky cez "\\n".', 'hint_en': 'Use :<12 specifier and join lines.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'formatuj_tabulku(["Meno", "Body"], [("Juraj", 100), ("Martin", 85)])', 'expected_output': 'Meno         | Body        \\n---------------------------\\nJuraj        | 100         \\nMartin       | 85         ', 'test_code': 'assert formatuj_tabulku(["Meno", "Body"], [("Juraj", 100), ("Martin", 85)]) == "Meno         | Body        \\n---------------------------\\nJuraj        | 100         \\nMartin       | 85         "', 'is_hidden': False}]}]

