COMPANIONS[(8, 1)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Bezpečný prístup k prvku zoznamu', 'title_en': 'Exercise 2 (Medium): Safe List Index Access', 'instructions_sk': 'Napíš funkciu `bezpecny_index(zoznam, index, predvolena=None)`: vráti `zoznam[index]`. Ak index prekročí rozsah (`IndexError`), vráti `predvolena`.', 'instructions_en': 'Write `bezpecny_index(zoznam, index, predvolena=None)` catching IndexError.', 'starter_code': 'def bezpecny_index(zoznam, index, predvolena=None):\n    pass\n', 'solution_code': 'def bezpecny_index(zoznam, index, predvolena=None):\n    try:\n        return zoznam[index]\n    except IndexError:\n        return predvolena\n', 'explanation_sk': 'Ošetrenie IndexError pomocou try-except.', 'explanation_en': 'Guarding against IndexError with try-except.', 'hint_sk': 'try: return zoznam[index] except IndexError: return predvolena', 'hint_en': 'Wrap index access in try-except IndexError.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'bezpecny_index([10, 20, 30], 1)', 'expected_output': '20', 'test_code': 'assert bezpecny_index([10, 20, 30], 1) == 20', 'is_hidden': False}, {'input_data': 'bezpecny_index([10, 20], 5, predvolena=-1)', 'expected_output': '-1', 'test_code': 'assert bezpecny_index([10, 20], 5, predvolena=-1) == -1', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Bezpečná textová kalkulačka', 'title_en': 'Exercise 3 (Boss Challenge): Safe String Math Evaluator', 'instructions_sk': 'Napíš funkciu `bezpecny_vypocet(a_str, b_str, op)`: prevedie vstupy na float a vykoná operáciu `"+", "-", "*", "/"`. Ak nastane delenie nulou, vráti `"CHYBA: Delenie nulou"`. Ak vstupy nie sú čísla, vráti `"CHYBA: Neplatné číslo"`. Ak je operátor neznámy, vráti `"CHYBA: Neznámy operátor"`. Pri úspechu vráti zaokrúhlený float na 2 des. miesta.', 'instructions_en': 'Write `bezpecny_vypocet(a_str, b_str, op)` catching ValueError and ZeroDivisionError.', 'starter_code': 'def bezpecny_vypocet(a_str, b_str, op):\n    pass\n', 'solution_code': 'def bezpecny_vypocet(a_str, b_str, op):\n    try:\n        a = float(a_str)\n        b = float(b_str)\n    except (ValueError, TypeError):\n        return "CHYBA: Neplatné číslo"\n    if op == "+":\n        return round(a + b, 2)\n    elif op == "-":\n        return round(a - b, 2)\n    elif op == "*":\n        return round(a * b, 2)\n    elif op == "/":\n        try:\n            return round(a / b, 2)\n        except ZeroDivisionError:\n            return "CHYBA: Delenie nulou"\n    return "CHYBA: Neznámy operátor"\n', 'explanation_sk': 'Viacúrovňové ošetrenie ValueError a ZeroDivisionError.', 'explanation_en': 'Defensive multi-exception handling returning descriptive status messages.', 'hint_sk': 'try: a = float(a_str) ... except ValueError: return "CHYBA: Neplatné číslo"', 'hint_en': 'Catch conversion and arithmetic errors.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'bezpecny_vypocet("10", "2", "/")', 'expected_output': '5.0', 'test_code': 'assert bezpecny_vypocet("10", "2", "/") == 5.0', 'is_hidden': False}, {'input_data': 'bezpecny_vypocet("10", "0", "/")', 'expected_output': 'CHYBA: Delenie nulou', 'test_code': 'assert bezpecny_vypocet("10", "0", "/") == "CHYBA: Delenie nulou"', 'is_hidden': False}, {'input_data': 'bezpecny_vypocet("abc", "5", "+")', 'expected_output': 'CHYBA: Neplatné číslo', 'test_code': 'assert bezpecny_vypocet("abc", "5", "+") == "CHYBA: Neplatné číslo"', 'is_hidden': True}]}]

# === Modul 8, Lekcia 2 ===
COMPANIONS[(8, 2)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Spracovanie zoznamu riadkov s chybami', 'title_en': 'Exercise 2 (Medium): Parse Integer Lines with Error Log', 'instructions_sk': 'Napíš funkciu `spracuj_riadky(riadky)`: parameter je zoznam reťazcov. Funkcia vráti dvojicu `(platne_cisla, chybne_riadky)`, kde `platne_cisla` je zoznam úspešne prevedených intov a `chybne_riadky` je zoznam pôvodných reťazcov, ktoré zlyhali na `ValueError`.', 'instructions_en': 'Write `spracuj_riadky(riadky)` returning tuple (valid_ints, invalid_strings).', 'starter_code': 'def spracuj_riadky(riadky):\n    pass\n', 'solution_code': 'def spracuj_riadky(riadky):\n    platne = []\n    chybne = []\n    for r in riadky:\n        try:\n            platne.append(int(r.strip()))\n        except ValueError:\n            chybne.append(r)\n    return (platne, chybne)\n', 'explanation_sk': 'Rozdelenie záznamov do úspešných a neúspešných zoznamov.', 'explanation_en': 'Partitioning valid parsed integers and failed strings.', 'hint_sk': 'try: platne.append(int(r)) except ValueError: chybne.append(r)', 'hint_en': 'Use try-except appending to valid or error list.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'spracuj_riadky(["10", "abc", "25", "xyz"])', 'expected_output': '([10, 25], ["abc", "xyz"])', 'test_code': 'assert spracuj_riadky(["10", "abc", "25", "xyz"]) == ([10, 25], ["abc", "xyz"])', 'is_hidden': False}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Simulácia transakčného rollbacku v pamäti', 'title_en': 'Exercise 3 (Boss Challenge): In-Memory Transaction Rollback', 'instructions_sk': 'Napíš funkciu `vykonaj_transakcie(pociatocny_stav, operacie)`: `pociatocny_stav` je slovník `{ucet: zostatok}`, `operacie` je zoznam trojíc `(odkial, kam, suma)`. Ak pri akejkoľvek operácii účet neexistuje alebo nemá dostatočný zostatok, CELÁ transakcia zlyhá: stav sa vráti na pôvodný (rollback) a funkcia vráti `None`. Ak všetky prebehnú, vráti nový slovník zostatkov.', 'instructions_en': 'Write `vykonaj_transakcie(pociatocny_stav, operacie)` with atomic rollback semantics.', 'starter_code': 'def vykonaj_transakcie(pociatocny_stav, operacie):\n    pass\n', 'solution_code': 'def vykonaj_transakcie(pociatocny_stav, operacie):\n    stav = dict(pociatocny_stav)\n    try:\n        for odkial, kam, suma in operacie:\n            if odkial not in stav or kam not in stav:\n                raise ValueError("Neznámy účet")\n            if stav[odkial] < suma:\n                raise ValueError("Nedostatok prostriedkov")\n            stav[odkial] -= suma\n            stav[kam] += suma\n        return stav\n    except ValueError:\n        return None\n', 'explanation_sk': 'Atómová transakčná logika s návratom None pri rollbacku.', 'explanation_en': 'Atomic state mutation pattern catching validation errors.', 'hint_sk': 'Pracuj s kópiou stav = dict(pociatocny_stav) a vráť None ak nastane chyba.', 'hint_en': 'Operate on state copy returning None on failure.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'vykonaj_transakcie({"A": 100, "B": 50}, [("A", "B", 30)])', 'expected_output': '{"A": 70, "B": 80}', 'test_code': 'assert vykonaj_transakcie({"A": 100, "B": 50}, [("A", "B", 30)]) == {"A": 70, "B": 80}', 'is_hidden': False}, {'input_data': 'vykonaj_transakcie({"A": 10, "B": 50}, [("A", "B", 30)])', 'expected_output': 'None', 'test_code': 'assert vykonaj_transakcie({"A": 10, "B": 50}, [("A", "B", 30)]) is None', 'is_hidden': True}]}]

