COMPANIONS[(8, 3)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Validácia veku vyvolaním ValueError', 'title_en': 'Exercise 1 (Easy): Age Range Validation with raise', 'instructions_sk': 'Napíš funkciu `over_vek(vek)`: ak je `vek < 0` alebo `vek > 130`, vyvolá `ValueError("Neplatný vek")`. Inak vráti `True`.', 'instructions_en': 'Write `over_vek(vek)` raising ValueError if out of 0-130 range.', 'starter_code': 'def over_vek(vek):\n    pass\n', 'solution_code': 'def over_vek(vek):\n    if vek < 0 or vek > 130:\n        raise ValueError("Neplatný vek")\n    return True\n', 'explanation_sk': 'Vyvolanie výnimky príkazom raise ValueError.', 'explanation_en': 'Raising descriptive ValueError when boundaries are violated.', 'hint_sk': 'if vek < 0 or vek > 130: raise ValueError("Neplatný vek")', 'hint_en': 'Use raise ValueError.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'over_vek(25)', 'expected_output': 'True', 'test_code': 'assert over_vek(25) is True', 'is_hidden': False}, {'input_data': 'over_vek(-1)', 'expected_output': 'ValueError', 'test_code': 'try:\n    over_vek(-1)\n    assert False\nexcept ValueError:\n    pass', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Prísny validátor hesla s výnimkami', 'title_en': 'Exercise 3 (Boss Challenge): Strict Password Exception Guard', 'instructions_sk': 'Napíš funkciu `skontroluj_silu_hesla(heslo)`:\n- Ak dĺžka < 8: vyvolá `ValueError("Heslo je príliš krátke")`\n- Ak neobsahuje číslicu: vyvolá `ValueError("Heslo musí obsahovať číslicu")`\n- Ak neobsahuje veľké písmeno: vyvolá `ValueError("Heslo musí obsahovať veľké písmeno")`\nAk spĺňa všetko, vráti `True`.', 'instructions_en': 'Write `skontroluj_silu_hesla(heslo)` raising specific ValueError on violations.', 'starter_code': 'def skontroluj_silu_hesla(heslo):\n    pass\n', 'solution_code': 'def skontroluj_silu_hesla(heslo):\n    if len(heslo) < 8:\n        raise ValueError("Heslo je príliš krátke")\n    if not any(c.isdigit() for c in heslo):\n        raise ValueError("Heslo musí obsahovať číslicu")\n    if not any(c.isupper() for c in heslo):\n        raise ValueError("Heslo musí obsahovať veľké písmeno")\n    return True\n', 'explanation_sk': 'Defenzívna validácia viacerých pravidiel pomocou any() a raise.', 'explanation_en': 'Defensive validation enforcing security policies with descriptive exceptions.', 'hint_sk': 'Over dĺžku, any(c.isdigit() for c in heslo) a any(c.isupper() for c in heslo).', 'hint_en': 'Check length, digits, and uppercase using any().', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'skontroluj_silu_hesla("Codoro2027")', 'expected_output': 'True', 'test_code': 'assert skontroluj_silu_hesla("Codoro2027") is True', 'is_hidden': False}, {'input_data': 'skontroluj_silu_hesla("kratke")', 'expected_output': 'ValueError', 'test_code': 'try:\n    skontroluj_silu_hesla("kratke")\n    assert False\nexcept ValueError:\n    pass', 'is_hidden': True}]}]

