COMPANIONS[(9, 1)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Trieda Kniha s požičiavaním', 'title_en': 'Exercise 2 (Medium): Book Class with Lending Status', 'instructions_sk': 'Vytvor triedu `Kniha`:\n1. `__init__(self, nazov, autor)`: nastaví atribúty `nazov`, `autor` a `je_pozicana = False`.\n2. `pozicaj(self)`: ak je kniha voľná, nastaví `je_pozicana = True` a vráti `True`. Ak už je požičaná, vráti `False`.\n3. `vrat(self)`: nastaví `je_pozicana = False`.', 'instructions_en': 'Implement class `Kniha` with `pozicaj` and `vrat` methods.', 'starter_code': 'class Kniha:\n    pass\n', 'solution_code': 'class Kniha:\n    def __init__(self, nazov, autor):\n        self.nazov = nazov\n        self.autor = autor\n        self.je_pozicana = False\n    def pozicaj(self):\n        if self.je_pozicana:\n            return False\n        self.je_pozicana = True\n        return True\n    def vrat(self):\n        self.je_pozicana = False\n', 'explanation_sk': 'Správa stavu objektu pomocou booleovského atribútu.', 'explanation_en': 'Object state management using boolean flag.', 'hint_sk': 'if self.je_pozicana: return False; self.je_pozicana = True; return True', 'hint_en': 'Toggle boolean flag.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'k = Kniha("Python", "Guido"); k.pozicaj(); k.pozicaj()', 'expected_output': 'False', 'test_code': 'k = Kniha("Python", "Guido")\nassert k.pozicaj() is True\nassert k.pozicaj() is False\nk.vrat()\nassert k.je_pozicana is False', 'is_hidden': False}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Správca poličky kníh', 'title_en': 'Exercise 3 (Boss Challenge): Bookshelf Manager Class', 'instructions_sk': 'Vytvor triedu `Policka`:\n1. `__init__(self)`: `self.knihy = []`.\n2. `pridaj_knihu(self, kniha_obj)`: pridá objekt knihy do zoznamu.\n3. `hladaj_podla_autora(self, autor)`: vráti zoznam názvov kníh daného autora.\n4. `pocet_dostupnych(self)`: vráti počet kníh, ktoré NIE SÚ požičané (`not k.je_pozicana`).', 'instructions_en': 'Implement class `Policka` aggregating book objects.', 'starter_code': 'class Policka:\n    pass\n', 'solution_code': 'class Policka:\n    def __init__(self):\n        self.knihy = []\n    def pridaj_knihu(self, kniha):\n        self.knihy.append(kniha)\n    def hladaj_podla_autora(self, autor):\n        return [k.nazov for k in self.knihy if k.autor == autor]\n    def pocet_dostupnych(self):\n        return sum(1 for k in self.knihy if not getattr(k, "je_pozicana", False))\n', 'explanation_sk': 'Agregácia a vyhľadávanie v zozname objektov.', 'explanation_en': 'Object aggregation and querying attributes.', 'hint_sk': 'Prechádzaj self.knihy a filtruj k.autor == autor.', 'hint_en': 'Filter aggregated book list.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'p = Policka(); p.pridaj_knihu(Kniha("A", "Autor1")); p.pridaj_knihu(Kniha("B", "Autor1")); p.hladaj_podla_autora("Autor1")', 'expected_output': '["A", "B"]', 'test_code': 'k1 = Kniha("A", "Autor1")\nk2 = Kniha("B", "Autor1")\np = Policka()\np.pridaj_knihu(k1)\np.pridaj_knihu(k2)\nassert p.hladaj_podla_autora("Autor1") == ["A", "B"]\nassert p.pocet_dostupnych() == 2', 'is_hidden': False}]}]

