COMPANIONS[(9, 2)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Trieda Obdĺžnik s metódami', 'title_en': 'Exercise 1 (Easy): Rectangle Class', 'instructions_sk': 'Vytvor triedu `Obdlznik`:\n1. `__init__(self, sirka, vyska)`: nastaví atribúty `sirka` a `vyska`.\n2. `obvod(self)`: vráti $2 \\times (sirka + vyska)$.\n3. `obsah(self)`: vráti $sirka \\times vyska$.', 'instructions_en': 'Implement class `Obdlznik` with perimeter and area methods.', 'starter_code': 'class Obdlznik:\n    pass\n', 'solution_code': 'class Obdlznik:\n    def __init__(self, sirka, vyska):\n        self.sirka = sirka\n        self.vyska = vyska\n    def obvod(self):\n        return 2 * (self.sirka + self.vyska)\n    def obsah(self):\n        return self.sirka * self.vyska\n', 'explanation_sk': 'Základná definícia inštančných metód.', 'explanation_en': 'Basic OOP instance methods.', 'hint_sk': 'return 2 * (self.sirka + self.vyska)', 'hint_en': 'Define init, obvod and obsah.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'o = Obdlznik(5, 4); o.obvod(); o.obsah()', 'expected_output': '20', 'test_code': 'o = Obdlznik(5, 4)\nassert o.obvod() == 18\nassert o.obsah() == 20', 'is_hidden': False}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Trieda Odpočítavač (Timer/Counter)', 'title_en': 'Exercise 3 (Boss Challenge): Countdown Counter Class', 'instructions_sk': 'Vytvor triedu `Odpocitavac`:\n1. `__init__(self, start)`: uloží `self.start = start` a `self.aktualny = start`.\n2. `tik(self)`: ak `self.aktualny > 0`, zníži ho o 1 a vráti `self.aktualny`. Ak už je na nule, vráti 0.\n3. `reset(self)`: nastaví `self.aktualny = self.start`.\n4. `je_na_nule(self)`: vráti `True`, ak je `self.aktualny == 0`, inak `False`.', 'instructions_en': 'Implement countdown counter class with tick, reset, and zero check.', 'starter_code': 'class Odpocitavac:\n    pass\n', 'solution_code': 'class Odpocitavac:\n    def __init__(self, start):\n        self.start = start\n        self.aktualny = start\n    def tik(self):\n        if self.aktualny > 0:\n            self.aktualny -= 1\n        return self.aktualny\n    def reset(self):\n        self.aktualny = self.start\n    def je_na_nule(self):\n        return self.aktualny == 0\n', 'explanation_sk': 'Zapuzdrenie stavu odpočítavania do inštancie triedy.', 'explanation_en': 'Encapsulating counter lifecycle state inside class.', 'hint_sk': 'if self.aktualny > 0: self.aktualny -= 1', 'hint_en': 'Decrement if > 0.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'c = Odpocitavac(2); c.tik(); c.tik(); c.tik(); c.je_na_nule()', 'expected_output': 'True', 'test_code': 'c = Odpocitavac(2)\nassert c.tik() == 1\nassert c.tik() == 0\nassert c.tik() == 0\nassert c.je_na_nule() is True\nc.reset()\nassert c.aktualny == 2', 'is_hidden': False}]}]

