COMPANIONS[(9, 3)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Statické matematické utility', 'title_en': 'Exercise 1 (Easy): Static Math Utilities', 'instructions_sk': 'Vytvor triedu `MatematikaUtil` s dvoma statickými metódami `@staticmethod`:\n1. `je_kladne(x)`: vráti `True` ak `x > 0`, inak `False`.\n2. `mocnina(x, exp=2)`: vráti `x ** exp`.', 'instructions_en': 'Implement class `MatematikaUtil` with @staticmethod methods.', 'starter_code': 'class MatematikaUtil:\n    pass\n', 'solution_code': 'class MatematikaUtil:\n    @staticmethod\n    def je_kladne(x):\n        return x > 0\n    @staticmethod\n    def mocnina(x, exp=2):\n        return x ** exp\n', 'explanation_sk': 'Použitie dekorátora @staticmethod.', 'explanation_en': 'Static methods decoupled from instance reference.', 'hint_sk': '@staticmethod def je_kladne(x): return x > 0', 'hint_en': 'Decorate methods with @staticmethod.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'MatematikaUtil.je_kladne(5); MatematikaUtil.mocnina(3, 3)', 'expected_output': '27', 'test_code': 'assert MatematikaUtil.je_kladne(5) is True\nassert MatematikaUtil.je_kladne(-2) is False\nassert MatematikaUtil.mocnina(3, 3) == 27', 'is_hidden': False}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Nastavenia s triednym počítadlom zmien', 'title_en': 'Exercise 3 (Boss Challenge): Class-Level Mutation Counter', 'instructions_sk': 'Vytvor triedu `NastaveniaAppky`:\n1. Má triedny atribút `pocet_zmien = 0` a `konfiguracia = {}`.\n2. `@classmethod nastav(cls, kluc, hodnota)`: uloží do `cls.konfiguracia[kluc] = hodnota` a navýši `cls.pocet_zmien += 1`.\n3. `@classmethod ziskaj(cls, kluc, default=None)`: vráti hodnotu z konfigurácie.', 'instructions_en': 'Implement class `NastaveniaAppky` with classmethod mutation tracker.', 'starter_code': 'class NastaveniaAppky:\n    pass\n', 'solution_code': 'class NastaveniaAppky:\n    pocet_zmien = 0\n    konfiguracia = {}\n    @classmethod\n    def nastav(cls, kluc, hodnota):\n        cls.konfiguracia[kluc] = hodnota\n        cls.pocet_zmien += 1\n    @classmethod\n    def ziskaj(cls, kluc, default=None):\n        return cls.konfiguracia.get(kluc, default)\n', 'explanation_sk': 'Zdieľaný stav triedy riadený cez @classmethod.', 'explanation_en': 'Class-level state mutation using @classmethod decorator.', 'hint_sk': 'cls.konfiguracia[kluc] = hodnota; cls.pocet_zmien += 1', 'hint_en': 'Mutate cls.konfiguracia and increment cls.pocet_zmien.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'NastaveniaAppky.nastav("theme", "dark"); NastaveniaAppky.ziskaj("theme")', 'expected_output': 'dark', 'test_code': 'NastaveniaAppky.nastav("theme", "dark")\nassert NastaveniaAppky.ziskaj("theme") == "dark"\nassert NastaveniaAppky.pocet_zmien >= 1', 'is_hidden': False}]}]

