COMPANIONS[(9, 4)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Trieda Kruh s @property obsah', 'title_en': 'Exercise 1 (Easy): Circle Class with @property Area', 'instructions_sk': 'Vytvor triedu `Kruh`:\n1. `__init__(self, polomer)`: nastaví `self.polomer = polomer`.\n2. `@property obsah(self)`: vráti obsah kruhu $S = 3.14159 \\times polomer^2$ zaokrúhlený na 2 desatinné miesta.', 'instructions_en': 'Implement class `Kruh` with property obsah.', 'starter_code': 'class Kruh:\n    pass\n', 'solution_code': 'class Kruh:\n    def __init__(self, polomer):\n        self.polomer = polomer\n    @property\n    def obsah(self):\n        return round(3.14159 * (self.polomer ** 2), 2)\n', 'explanation_sk': 'Použitie dekorátora @property pre dynamicky počítaný atribút.', 'explanation_en': 'Dynamic computed attribute using @property.', 'hint_sk': '@property def obsah(self): return round(3.14159 * (self.polomer ** 2), 2)', 'hint_en': 'Use @property.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'k = Kruh(10); k.obsah', 'expected_output': '314.16', 'test_code': 'k = Kruh(10)\nassert k.obsah == 314.16', 'is_hidden': False}]}, {'order': 2, 'title_sk': 'Úloha 2 (Stredná): Zapuzdrenie platu cez getter a setter', 'title_en': 'Exercise 2 (Medium): Encapsulated Salary Property', 'instructions_sk': 'Vytvor triedu `Zamestnanec`:\n1. `__init__(self, meno, plat)`: nastaví `self.meno = meno` a cez setter nastaví `plat`.\n2. `@property plat(self)`: vráti privátny atribút `self._plat`.\n3. `@plat.setter`: ak je nový plat $\\ge 0$, nastaví ho. Ak je záporný, vyvolá `ValueError("Plat nesmie byť záporný")`.', 'instructions_en': 'Implement class `Zamestnanec` with validated @plat.setter.', 'starter_code': 'class Zamestnanec:\n    pass\n', 'solution_code': 'class Zamestnanec:\n    def __init__(self, meno, plat):\n        self.meno = meno\n        self.plat = plat\n    @property\n    def plat(self):\n        return self._plat\n    @plat.setter\n    def plat(self, hodnota):\n        if hodnota < 0:\n            raise ValueError("Plat nesmie byť záporný")\n        self._plat = hodnota\n', 'explanation_sk': 'Zapuzdrenie a defenzívna validácia v property setter metóde.', 'explanation_en': 'Data encapsulation protecting internal state via setter validation.', 'hint_sk': '@plat.setter def plat(self, h): if h < 0: raise ValueError(...) self._plat = h', 'hint_en': 'Validate in setter.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'z = Zamestnanec("Peter", 1200); z.plat = 1500; z.plat', 'expected_output': '1500', 'test_code': 'z = Zamestnanec("Peter", 1200)\nassert z.plat == 1200\nz.plat = 1500\nassert z.plat == 1500\ntry:\n    z.plat = -100\n    assert False\nexcept ValueError:\n    pass', 'is_hidden': False}]}]

