COMPANIONS[(10, 2)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Geometrický polymorfizmus útvarov', 'title_en': 'Exercise 1 (Easy): Geometric Polymorphism', 'instructions_sk': 'Vytvor triedy `Stvorec(strana)` a `ObdlznikUtvar(a, b)`: obe majú metódu `obsah(self)`. Funkcia `celkovy_obsah(utvary)` vezme zoznam ľubovoľných útvarov a pomocou polymorfizmu vráti súčet ich obsahov.', 'instructions_en': 'Implement classes with polymorphic obsah() and aggregator celkovy_obsah().', 'starter_code': 'class Stvorec:\n    pass\n\nclass ObdlznikUtvar:\n    pass\n\ndef celkovy_obsah(utvary):\n    pass\n', 'solution_code': 'class Stvorec:\n    def __init__(self, strana):\n        self.strana = strana\n    def obsah(self):\n        return self.strana ** 2\n\nclass ObdlznikUtvar:\n    def __init__(self, a, b):\n        self.a = a\n        self.b = b\n    def obsah(self):\n        return self.a * self.b\n\ndef celkovy_obsah(utvary):\n    return sum(u.obsah() for u in utvary)\n', 'explanation_sk': 'Polymorfné volanie rovnomennej metódy obsah() na rôznych triedach (Duck Typing).', 'explanation_en': 'Polymorphic duck typing aggregating instances via shared interface.', 'hint_sk': 'return sum(u.obsah() for u in utvary)', 'hint_en': 'Sum u.obsah() in loop.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'celkovy_obsah([Stvorec(4), ObdlznikUtvar(3, 5)])', 'expected_output': '31', 'test_code': 'assert celkovy_obsah([Stvorec(4), ObdlznikUtvar(3, 5)]) == 31', 'is_hidden': False}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Polymorfné platobné brány', 'title_en': 'Exercise 3 (Boss Challenge): Payment Gateway Polymorphism', 'instructions_sk': 'Vytvor triedy platobných metód:\n1. `KartaPlatba(poplatok_pct=2.0)`: metóda `spracuj(self, suma)` vráti celkovú sumu `suma * (1 + poplatok_pct / 100)` zaokrúhlenú na 2 des. miesta.\n2. `KryptoPlatba(sietovy_poplatok=1.5)`: metóda `spracuj(self, suma)` vráti `suma + sietovy_poplatok` zaokrúhlenú na 2 des. miesta.\nFunkcia `vyuctuj_objednavku(brana, suma)` zavolá `brana.spracuj(suma)`.', 'instructions_en': 'Implement polymorphic payment gateway processors.', 'starter_code': 'class KartaPlatba:\n    pass\n\nclass KryptoPlatba:\n    pass\n\ndef vyuctuj_objednavku(brana, suma):\n    pass\n', 'solution_code': 'class KartaPlatba:\n    def __init__(self, poplatok_pct=2.0):\n        self.poplatok_pct = poplatok_pct\n    def spracuj(self, suma):\n        return round(suma * (1 + self.poplatok_pct / 100.0), 2)\n\nclass KryptoPlatba:\n    def __init__(self, sietovy_poplatok=1.5):\n        self.sietovy_poplatok = sietovy_poplatok\n    def spracuj(self, suma):\n        return round(suma + self.sietovy_poplatok, 2)\n\ndef vyuctuj_objednavku(brana, suma):\n    return brana.spracuj(suma)\n', 'explanation_sk': 'Polymorfný návrhový vzor Strategy.', 'explanation_en': 'Strategy pattern using polymorphic interface.', 'hint_sk': 'Implementuj spracuj(self, suma) a vyuctuj_objednavku vráti brana.spracuj(suma).', 'hint_en': 'Implement spracuj and delegate.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'vyuctuj_objednavku(KartaPlatba(2.0), 100.0)', 'expected_output': '102.0', 'test_code': 'assert vyuctuj_objednavku(KartaPlatba(2.0), 100.0) == 102.0', 'is_hidden': False}, {'input_data': 'vyuctuj_objednavku(KryptoPlatba(2.5), 100.0)', 'expected_output': '102.5', 'test_code': 'assert vyuctuj_objednavku(KryptoPlatba(2.5), 100.0) == 102.5', 'is_hidden': True}]}]

