COMPANIONS[(11, 1)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Rozpoznanie konštantnej zložitosti O(1)', 'title_en': 'Exercise 1 (Easy): Constant Time Complexity Recognition', 'instructions_sk': 'Napíš funkciu `je_konstantny_cas(operacia)`: vráti `True`, ak je operácia v Pythone bežne $O(1)$: `"dict_lookup"`, `"list_index"`, `"set_add"`, `"list_append"`. Pre `"list_sort"`, `"list_search"`, `"string_find"` vráti `False`.', 'instructions_en': 'Write `je_konstantny_cas(operacia)` returning True for O(1) operations.', 'starter_code': 'def je_konstantny_cas(operacia):\n    pass\n', 'solution_code': 'def je_konstantny_cas(operacia):\n    o1_ops = {"dict_lookup", "list_index", "set_add", "list_append"}\n    return operacia in o1_ops\n', 'explanation_sk': 'Teoretické overenie časovej zložitosti operácií v Pythone.', 'explanation_en': 'Theoretical Big-O lookup verification.', 'hint_sk': 'return operacia in {"dict_lookup", "list_index", "set_add", "list_append"}', 'hint_en': 'Check membership in O(1) set.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'je_konstantny_cas("dict_lookup")', 'expected_output': 'True', 'test_code': 'assert je_konstantny_cas("dict_lookup") is True', 'is_hidden': False}, {'input_data': 'je_konstantny_cas("list_sort")', 'expected_output': 'False', 'test_code': 'assert je_konstantny_cas("list_sort") is False', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Maximálny súčet podpoľa v O(n) (Kadaneho algoritmus)', 'title_en': 'Exercise 3 (Boss Challenge): Maximum Subarray Sum (Kadane)', 'instructions_sk': 'Napíš funkciu `max_podpole_sucet(cisla)`: pomocou Kadaneho algoritmu v lineárnom čase $O(n)$ nájde maximálny možný súčet súvislého podpoľa. Napr. pre `[-2, 1, -3, 4, -1, 2, 1, -5, 4]` vráti `6` (podpole `[4, -1, 2, 1]`). Ak je zoznam prázdny, vráti `0`.', 'instructions_en': 'Write `max_podpole_sucet(cisla)` using Kadane algorithm in O(n) time.', 'starter_code': 'def max_podpole_sucet(cisla):\n    pass\n', 'solution_code': 'def max_podpole_sucet(cisla):\n    if not cisla:\n        return 0\n    max_so_far = cisla[0]\n    curr_max = cisla[0]\n    for x in cisla[1:]:\n        curr_max = max(x, curr_max + x)\n        max_so_far = max(max_so_far, curr_max)\n    return max_so_far\n', 'explanation_sk': 'Kadaneho algoritmus rieši maximum subarray problem v optimálnom lineárnom čase O(n).', 'explanation_en': 'Kadane dynamic programming algorithm for maximum contiguous subarray sum.', 'hint_sk': 'curr_max = max(x, curr_max + x); max_so_far = max(max_so_far, curr_max)', 'hint_en': 'Use Kadane recurrence.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'max_podpole_sucet([-2, 1, -3, 4, -1, 2, 1, -5, 4])', 'expected_output': '6', 'test_code': 'assert max_podpole_sucet([-2, 1, -3, 4, -1, 2, 1, -5, 4]) == 6', 'is_hidden': False}, {'input_data': 'max_podpole_sucet([])', 'expected_output': '0', 'test_code': 'assert max_podpole_sucet([]) == 0', 'is_hidden': True}]}]

