COMPANIONS[(11, 2)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Lineárne sekvenčné vyhľadávanie', 'title_en': 'Exercise 1 (Easy): Linear Sequential Search', 'instructions_sk': 'Napíš funkciu `linearny_search(zoznam, ciel)`: prejde zoznam od začiatku a vráti index prvého výskytu prvku `ciel`. Ak sa v zozname nenachádza, vráti `-1`.', 'instructions_en': 'Write `linearny_search(zoznam, ciel)` returning index of target or -1.', 'starter_code': 'def linearny_search(zoznam, ciel):\n    pass\n', 'solution_code': 'def linearny_search(zoznam, ciel):\n    for i, x in enumerate(zoznam):\n        if x == ciel:\n            return i\n    return -1\n', 'explanation_sk': 'Klasické lineárne vyhľadávanie v čase O(n).', 'explanation_en': 'Linear scan running in O(n) worst-case time.', 'hint_sk': 'for i, x in enumerate(zoznam): if x == ciel: return i', 'hint_en': 'Scan elements linearly.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'linearny_search([10, 42, 5], 42)', 'expected_output': '1', 'test_code': 'assert linearny_search([10, 42, 5], 42) == 1', 'is_hidden': False}, {'input_data': 'linearny_search([1, 2], 99)', 'expected_output': '-1', 'test_code': 'assert linearny_search([1, 2], 99) == -1', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Prvý a posledný výskyt prvku binárnym vyhľadávaním', 'title_en': 'Exercise 3 (Boss Challenge): First and Last Occurrence Binary Search', 'instructions_sk': 'Napíš funkciu `hladaj_rozsah(zoradeny_zoznam, ciel)`: v zoradenom zozname nájde index prvého a posledného výskytu hodnoty `ciel` v čase $O(\\log n)$. Vráti dvojicu `(prvy_index, posledny_index)`. Ak sa prvok nenachádza, vráti `(-1, -1)`.', 'instructions_en': 'Write `hladaj_rozsah(zoradeny_zoznam, ciel)` returning (first_idx, last_idx) in O(log n).', 'starter_code': 'def hladaj_rozsah(zoradeny_zoznam, ciel):\n    pass\n', 'solution_code': 'def hladaj_rozsah(zoradeny_zoznam, ciel):\n    def najdi_kraj(hladaj_prvy):\n        low, high = 0, len(zoradeny_zoznam) - 1\n        idx = -1\n        while low <= high:\n            mid = (low + high) // 2\n            if zoradeny_zoznam[mid] == ciel:\n                idx = mid\n                if hladaj_prvy:\n                    high = mid - 1\n                else:\n                    low = mid + 1\n            elif zoradeny_zoznam[mid] < ciel:\n                low = mid + 1\n            else:\n                high = mid - 1\n        return idx\n    first = najdi_kraj(True)\n    if first == -1:\n        return (-1, -1)\n    last = najdi_kraj(False)\n    return (first, last)\n', 'explanation_sk': 'Dvojité binárne vyhľadávanie v logaritmickom čase O(log n).', 'explanation_en': 'Dual binary search finding lower and upper boundaries in O(log n).', 'hint_sk': 'Uprav binárne vyhľadávanie: pri zhode pokračuj doľava (first) alebo doprava (last).', 'hint_en': 'Modify binary search to continue towards boundary on match.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'hladaj_rozsah([5, 7, 7, 8, 8, 10], 8)', 'expected_output': '(3, 4)', 'test_code': 'assert hladaj_rozsah([5, 7, 7, 8, 8, 10], 8) == (3, 4)', 'is_hidden': False}, {'input_data': 'hladaj_rozsah([1, 2, 3], 9)', 'expected_output': '(-1, -1)', 'test_code': 'assert hladaj_rozsah([1, 2, 3], 9) == (-1, -1)', 'is_hidden': True}]}]

