COMPANIONS[(11, 3)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Overenie usporiadania zoznamu', 'title_en': 'Exercise 1 (Easy): Check if List is Sorted', 'instructions_sk': 'Napíš funkciu `je_zoradeny(cisla)`: vráti `True`, ak je zoznam čísel vzostupne usporiadaný (každý prvok $\\le$ nasledujúci), inak `False`.', 'instructions_en': 'Write `je_zoradeny(cisla)` returning True if sorted ascending.', 'starter_code': 'def je_zoradeny(cisla):\n    pass\n', 'solution_code': 'def je_zoradeny(cisla):\n    return all(cisla[i] <= cisla[i + 1] for i in range(len(cisla) - 1))\n', 'explanation_sk': 'Kontrola usporiadania susedných prvkov v čase O(n).', 'explanation_en': 'Linear scan verifying monotonic non-decreasing order.', 'hint_sk': 'all(cisla[i] <= cisla[i+1] for i in range(len(cisla)-1))', 'hint_en': 'Check adjacent pairs.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'je_zoradeny([1, 2, 2, 5, 9])', 'expected_output': 'True', 'test_code': 'assert je_zoradeny([1, 2, 2, 5, 9]) is True', 'is_hidden': False}, {'input_data': 'je_zoradeny([1, 5, 2])', 'expected_output': 'False', 'test_code': 'assert je_zoradeny([1, 5, 2]) is False', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Implementácia triedenia vkladaním (Insertion Sort)', 'title_en': 'Exercise 3 (Boss Challenge): Insertion Sort Implementation', 'instructions_sk': 'Napíš funkciu `insertion_sort(cisla)`: vráti nový vzostupne usporiadaný zoznam pomocou algoritmu Insertion Sort (triedenie vkladaním prvku do už usporiadanej ľavej časti).', 'instructions_en': 'Write `insertion_sort(cisla)` returning sorted list using insertion sort.', 'starter_code': 'def insertion_sort(cisla):\n    pass\n', 'solution_code': 'def insertion_sort(cisla):\n    a = list(cisla)\n    for i in range(1, len(a)):\n        kluc = a[i]\n        j = i - 1\n        while j >= 0 and a[j] > kluc:\n            a[j + 1] = a[j]\n            j -= 1\n        a[j + 1] = kluc\n    return a\n', 'explanation_sk': 'Klasická implementácia Insertion Sort s posunom prvkov doprava.', 'explanation_en': 'Standard insertion sort shifting larger elements rightward.', 'hint_sk': 'Prechádzaj od 1, ulož kluc = a[i] a posúvaj a[j] doprava kým a[j] > kluc.', 'hint_en': 'Insert key into sorted left partition.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'insertion_sort([12, 11, 13, 5, 6])', 'expected_output': '[5, 6, 11, 12, 13]', 'test_code': 'assert insertion_sort([12, 11, 13, 5, 6]) == [5, 6, 11, 12, 13]', 'is_hidden': False}]}]

