COMPANIONS[(11, 4)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Zliatie dvoch zoradených zoznamov', 'title_en': 'Exercise 1 (Easy): Merge Two Sorted Lists', 'instructions_sk': 'Napíš funkciu `zluc_dva_zoradene(a, b)`: vezme dva už zoradené zoznamy a spojí ich do jedného nového zoradeného zoznamu v čase $O(n + m)$ (zlučovací krok Merge Sortu).', 'instructions_en': 'Write `zluc_dva_zoradene(a, b)` merging two sorted lists in O(n+m).', 'starter_code': 'def zluc_dva_zoradene(a, b):\n    pass\n', 'solution_code': 'def zluc_dva_zoradene(a, b):\n    i, j = 0, 0\n    vysledok = []\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            vysledok.append(a[i])\n            i += 1\n        else:\n            vysledok.append(b[j])\n            j += 1\n    vysledok.extend(a[i:])\n    vysledok.extend(b[j:])\n    return vysledok\n', 'explanation_sk': 'Lineárne zliatie dvoch ukazovateľov i a j.', 'explanation_en': 'Two-pointer merge step of merge sort.', 'hint_sk': 'Porovnávaj a[i] a b[j], menší pridaj a posuň index. Na záver doplň zvyšok.', 'hint_en': 'Two-pointer comparison loop.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'zluc_dva_zoradene([1, 3, 5], [2, 4, 6])', 'expected_output': '[1, 2, 3, 4, 5, 6]', 'test_code': 'assert zluc_dva_zoradene([1, 3, 5], [2, 4, 6]) == [1, 2, 3, 4, 5, 6]', 'is_hidden': False}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Kompletný rekurzívny Merge Sort', 'title_en': 'Exercise 3 (Boss Challenge): Full Recursive Merge Sort', 'instructions_sk': 'Napíš funkciu `merge_sort(cisla)`: implementuje kompletný algoritmus triedenia zlučovaním (Merge Sort) s časovou zložitosťou $O(n \\log n)$. Pre zoznam s $\\le 1$ prvkami vráti priamo kópiu zoznamu.', 'instructions_en': 'Write `merge_sort(cisla)` implementing full recursive merge sort in O(n log n).', 'starter_code': 'def merge_sort(cisla):\n    pass\n', 'solution_code': 'def merge_sort(cisla):\n    if len(cisla) <= 1:\n        return list(cisla)\n    stred = len(cisla) // 2\n    lavy = merge_sort(cisla[:stred])\n    pravy = merge_sort(cisla[stred:])\n    i = j = 0\n    vysledok = []\n    while i < len(lavy) and j < len(pravy):\n        if lavy[i] <= pravy[j]:\n            vysledok.append(lavy[i])\n            i += 1\n        else:\n            vysledok.append(pravy[j])\n            j += 1\n    vysledok.extend(lavy[i:])\n    vysledok.extend(pravy[j:])\n    return vysledok\n', 'explanation_sk': 'Rozdeľ a panuj (Divide and Conquer) rekurzívne delenie a zlučovanie v O(n log n).', 'explanation_en': 'Classic divide and conquer merge sort running in O(n log n).', 'hint_sk': 'Rozdeľ v strede, zavolaj merge_sort na ľavú aj pravú polovicu a zlej ich.', 'hint_en': 'Divide at midpoint and recursively merge.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'merge_sort([38, 27, 43, 3, 9, 82, 10])', 'expected_output': '[3, 9, 10, 27, 38, 43, 82]', 'test_code': 'assert merge_sort([38, 27, 43, 3, 9, 82, 10]) == [3, 9, 10, 27, 38, 43, 82]', 'is_hidden': False}]}]

