COMPANIONS[(11, 5)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Luhnov algoritmus pre platobné karty', 'title_en': 'Exercise 1 (Easy): Luhn Checksum Algorithm', 'instructions_sk': 'Napíš funkciu `luhn_cifra(cislo_str)`: spočíta kontrolnú cifru Luhnovho algoritmu. Každú druhú cifru odzadu zdvojnásobí (ak je $>9$, odčíta 9) a sčíta všetky cifry. Ak je celkový súčet deliteľný 10 (`sum % 10 == 0`), vráti `True`, inak `False`.', 'instructions_en': 'Write `luhn_cifra(cislo_str)` validating credit card checksum.', 'starter_code': 'def luhn_cifra(cislo_str):\n    pass\n', 'solution_code': 'def luhn_cifra(cislo_str):\n    digits = [int(c) for c in cislo_str if c.isdigit()]\n    if not digits:\n        return False\n    spolu = 0\n    otocene = digits[::-1]\n    for i, d in enumerate(otocene):\n        if i % 2 == 1:\n            d *= 2\n            if d > 9:\n                d -= 9\n        spolu += d\n    return spolu % 10 == 0\n', 'explanation_sk': 'Luhnov algoritmus (Modulus 10) validujúci platobné karty.', 'explanation_en': 'Standard Luhn check formula validating payment card checksum.', 'hint_sk': 'Otoč cifry, pre nepárne indexy zdvojnásob a ak > 9 odpočítaj 9. Spolu % 10 == 0.', 'hint_en': 'Reverse digits, double alternate digits, check modulo 10.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'luhn_cifra("79927398713")', 'expected_output': 'True', 'test_code': 'assert luhn_cifra("79927398713") is True', 'is_hidden': False}, {'input_data': 'luhn_cifra("79927398710")', 'expected_output': 'False', 'test_code': 'assert luhn_cifra("79927398710") is False', 'is_hidden': True}]}, {'order': 2, 'title_sk': 'Úloha 2 (Stredná): Eratostenovo sito pre prvočísla', 'title_en': 'Exercise 2 (Medium): Sieve of Eratosthenes', 'instructions_sk': 'Napíš funkciu `eratostenes(n)`: pomocou Eratostenovho sita vráti zoznam všetkých prvočísel menších alebo rovných `n`. Napr. pre 10 vráti `[2, 3, 5, 7]`. Pre $n < 2$ vráti `[]`.', 'instructions_en': 'Write `eratostenes(n)` generating primes up to n using Sieve of Eratosthenes.', 'starter_code': 'def eratostenes(n):\n    pass\n', 'solution_code': 'def eratostenes(n):\n    if n < 2:\n        return []\n    je_prv = [True] * (n + 1)\n    je_prv[0] = je_prv[1] = False\n    for p in range(2, int(n**0.5) + 1):\n        if je_prv[p]:\n            for i in range(p * p, n + 1, p):\n                je_prv[i] = False\n    return [p for p in range(2, n + 1) if je_prv[p]]\n', 'explanation_sk': 'Eratostenovo sito pre generovanie prvočísel v čase O(n log log n).', 'explanation_en': 'Sieve of Eratosthenes generating prime numbers up to n.', 'hint_sk': 'Vytvor pole boolov a pre každé prvočíslo p vyškrtaj násobky od p*p s krokom p.', 'hint_en': 'Mark multiples of each prime starting from p*p.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'eratostenes(10)', 'expected_output': '[2, 3, 5, 7]', 'test_code': 'assert eratostenes(10) == [2, 3, 5, 7]', 'is_hidden': False}, {'input_data': 'eratostenes(1)', 'expected_output': '[]', 'test_code': 'assert eratostenes(1) == []', 'is_hidden': True}]}]

