COMPANIONS[(3, 1)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Kalkulačka poštovného podľa hmotnosti', 'title_en': 'Exercise 2 (Medium): Postage Weight Rate Calculator', 'instructions_sk': 'Napíš funkciu `cena_postovneho(vaha_g)`: do 100g stojí 1.50 EUR, do 500g stojí 2.50 EUR, do 1000g stojí 3.50 EUR, nad 1000g stojí 5.00 EUR. Vráti float.', 'instructions_en': 'Write `cena_postovneho(vaha_g)` returning tier price float.', 'starter_code': 'def cena_postovneho(vaha_g):\n    pass\n', 'solution_code': 'def cena_postovneho(vaha_g):\n    if vaha_g <= 100:\n        return 1.50\n    elif vaha_g <= 500:\n        return 2.50\n    elif vaha_g <= 1000:\n        return 3.50\n    return 5.00\n', 'explanation_sk': 'Viacstupňové vetvenie if-elif-else.', 'explanation_en': 'Tiered branch logic returning float postage fee.', 'hint_sk': 'if vaha_g <= 100: return 1.50 ...', 'hint_en': 'Check intervals sequentially.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'cena_postovneho(80)', 'expected_output': '1.5', 'test_code': 'assert cena_postovneho(80) == 1.5', 'is_hidden': False}, {'input_data': 'cena_postovneho(600)', 'expected_output': '3.5', 'test_code': 'assert cena_postovneho(600) == 3.5', 'is_hidden': False}, {'input_data': 'cena_postovneho(1500)', 'expected_output': '5.0', 'test_code': 'assert cena_postovneho(1500) == 5.0', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Klasifikácia trojuholníka', 'title_en': 'Exercise 3 (Boss Challenge): Triangle Geometry Classifier', 'instructions_sk': 'Napíš funkciu `typ_trojuholnika(a, b, c)`: najprv over trojuholníkovú nerovnosť ($a+b>c \\land a+c>b \\land b+c>a$). Ak neplatí, vráti `"Nemožný"`. Inak: ak sú všetky strany rovnaké `"Rovnostranný"`, ak dve rovnaké `"Rovnoramenný"`, inak `"Rôznostranný"`.', 'instructions_en': 'Write `typ_trojuholnika(a, b, c)` classifying triangle type.', 'starter_code': 'def typ_trojuholnika(a, b, c):\n    pass\n', 'solution_code': 'def typ_trojuholnika(a, b, c):\n    if not (a + b > c and a + c > b and b + c > a):\n        return "Nemožný"\n    if a == b == c:\n        return "Rovnostranný"\n    elif a == b or a == c or b == c:\n        return "Rovnoramenný"\n    return "Rôznostranný"\n', 'explanation_sk': 'Overenie trojuholníkovej nerovnosti a rovnosti strán.', 'explanation_en': 'Triangle inequality check followed by side equality branches.', 'hint_sk': 'if not (a+b>c and a+c>b and b+c>a): return "Nemožný"', 'hint_en': 'Check triangle inequality first.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'typ_trojuholnika(3, 3, 3)', 'expected_output': 'Rovnostranný', 'test_code': 'assert typ_trojuholnika(3, 3, 3) == "Rovnostranný"', 'is_hidden': False}, {'input_data': 'typ_trojuholnika(1, 2, 10)', 'expected_output': 'Nemožný', 'test_code': 'assert typ_trojuholnika(1, 2, 10) == "Nemožný"', 'is_hidden': False}, {'input_data': 'typ_trojuholnika(3, 4, 5)', 'expected_output': 'Rôznostranný', 'test_code': 'assert typ_trojuholnika(3, 4, 5) == "Rôznostranný"', 'is_hidden': True}]}]

