COMPANIONS[(3, 2)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Určenie kvadrantu bodu v 2D rovine', 'title_en': 'Exercise 2 (Medium): 2D Cartesian Quadrant Finder', 'instructions_sk': 'Napíš funkciu `urci_kvadrant(x, y)`: vráti 1 ak $x>0, y>0$; 2 ak $x<0, y>0$; 3 ak $x<0, y<0$; 4 ak $x>0, y<0$; a 0 ak bod leží na niektorej z osí.', 'instructions_en': 'Write `urci_kvadrant(x, y)` returning quadrant number 1, 2, 3, 4 or 0.', 'starter_code': 'def urci_kvadrant(x, y):\n    pass\n', 'solution_code': 'def urci_kvadrant(x, y):\n    if x == 0 or y == 0:\n        return 0\n    if x > 0 and y > 0:\n        return 1\n    elif x < 0 and y > 0:\n        return 2\n    elif x < 0 and y < 0:\n        return 3\n    return 4\n', 'explanation_sk': 'Vetvenie pre jednotlivé kvadranty v rovine.', 'explanation_en': 'Cartesian quadrant branching with axis zero guard.', 'hint_sk': 'if x == 0 or y == 0: return 0', 'hint_en': 'Guard against axes first.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'urci_kvadrant(5, 5)', 'expected_output': '1', 'test_code': 'assert urci_kvadrant(5, 5) == 1', 'is_hidden': False}, {'input_data': 'urci_kvadrant(-2, 4)', 'expected_output': '2', 'test_code': 'assert urci_kvadrant(-2, 4) == 2', 'is_hidden': False}, {'input_data': 'urci_kvadrant(0, 3)', 'expected_output': '0', 'test_code': 'assert urci_kvadrant(0, 3) == 0', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Progresívna daň z príjmu', 'title_en': 'Exercise 3 (Boss Challenge): Progressive Income Tax', 'instructions_sk': 'Napíš funkciu `vypocitaj_dan(prijem)`: do 10 000 EUR je sadzba 0%. Z časti príjmu medzi 10 000 a 40 000 EUR je sadzba 19%. Z časti príjmu nad 40 000 EUR je sadzba 25%. Vráti daň zaokrúhlenú na 2 desatinné miesta.', 'instructions_en': 'Write `vypocitaj_dan(prijem)` calculating progressive bracket tax.', 'starter_code': 'def vypocitaj_dan(prijem):\n    pass\n', 'solution_code': 'def vypocitaj_dan(prijem):\n    if prijem <= 10000:\n        return 0.0\n    elif prijem <= 40000:\n        zaklad = prijem - 10000\n        return round(zaklad * 0.19, 2)\n    else:\n        dan1 = 30000 * 0.19\n        dan2 = (prijem - 40000) * 0.25\n        return round(dan1 + dan2, 2)\n', 'explanation_sk': 'Výpočet progresívnej dane v daňových pásmach.', 'explanation_en': 'Progressive bracket tax computation with marginal tax rates.', 'hint_sk': 'Sleduj prírastok príjmu v jednotlivých pásmach (10k a 40k).', 'hint_en': 'Compute tax on amount within each bracket.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'vypocitaj_dan(8000)', 'expected_output': '0.0', 'test_code': 'assert vypocitaj_dan(8000) == 0.0', 'is_hidden': False}, {'input_data': 'vypocitaj_dan(20000)', 'expected_output': '1900.0', 'test_code': 'assert vypocitaj_dan(20000) == 1900.0', 'is_hidden': False}, {'input_data': 'vypocitaj_dan(50000)', 'expected_output': '8200.0', 'test_code': 'assert vypocitaj_dan(50000) == 8200.0', 'is_hidden': True}]}]

