COMPANIONS[(3, 5)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Semafor akcia pomocou match-case', 'title_en': 'Exercise 1 (Easy): Traffic Light Action', 'instructions_sk': 'Napíš funkciu `semafor_akcia(farba)`: pre "cervena" vráti "Stoj", pre "oranzova" vráti "Priprav sa", pre "zelena" vráti "Voľno", a pre akúkoľvek inú farbu vráti "Porucha". Použi `match-case`.', 'instructions_en': 'Write `semafor_akcia(farba)` matching traffic light colors.', 'starter_code': 'def semafor_akcia(farba):\n    pass\n', 'solution_code': 'def semafor_akcia(farba):\n    match farba.lower():\n        case "cervena":\n            return "Stoj"\n        case "oranzova":\n            return "Priprav sa"\n        case "zelena":\n            return "Voľno"\n        case _:\n            return "Porucha"\n', 'explanation_sk': 'Použitie konštrukcie match-case s predvolenou vetvou case _.', 'explanation_en': 'Pattern matching using match-case and wildcard case _.', 'hint_sk': 'match farba.lower(): case "cervena": ... case _:', 'hint_en': 'Use match case syntax.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'semafor_akcia("cervena")', 'expected_output': 'Stoj', 'test_code': 'assert semafor_akcia("cervena") == "Stoj"', 'is_hidden': False}, {'input_data': 'semafor_akcia("zelena")', 'expected_output': 'Voľno', 'test_code': 'assert semafor_akcia("zelena") == "Voľno"', 'is_hidden': False}, {'input_data': 'semafor_akcia("modra")', 'expected_output': 'Porucha', 'test_code': 'assert semafor_akcia("modra") == "Porucha"', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Kalkulačka operátorov s match-case', 'title_en': 'Exercise 3 (Boss Challenge): Match-Case Calculator', 'instructions_sk': 'Napíš funkciu `kalkulacka_op(a, b, op)`: podporuje operátory `"+", "-", "*", "/", "**"`. Pri delení nulou alebo neznámom operátore vyvolá `ValueError`. Výsledok vráti ako číslo.', 'instructions_en': 'Write `kalkulacka_op(a, b, op)` with math operators raising ValueError on zero division or invalid op.', 'starter_code': 'def kalkulacka_op(a, b, op):\n    pass\n', 'solution_code': 'def kalkulacka_op(a, b, op):\n    match op:\n        case "+":\n            return a + b\n        case "-":\n            return a - b\n        case "*":\n            return a * b\n        case "/":\n            if b == 0:\n                raise ValueError("Delenie nulou")\n            return a / b\n        case "**":\n            return a ** b\n        case _:\n            raise ValueError(f"Neznámy operátor: {op}")\n', 'explanation_sk': 'Porovnanie vzorov operátorov s ošetrením chýb.', 'explanation_en': 'Pattern matching operators with defensive ValueError handling.', 'hint_sk': 'match op: case "+": ... case "/": if b == 0: raise ValueError(...)', 'hint_en': 'Use match case and raise ValueError on error.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'kalkulacka_op(10, 5, "+")', 'expected_output': '15', 'test_code': 'assert kalkulacka_op(10, 5, "+") == 15', 'is_hidden': False}, {'input_data': 'kalkulacka_op(2, 3, "**")', 'expected_output': '8', 'test_code': 'assert kalkulacka_op(2, 3, "**") == 8', 'is_hidden': False}, {'input_data': 'kalkulacka_op(10, 0, "/")', 'expected_output': 'ValueError', 'test_code': 'try:\n    kalkulacka_op(10, 0, "/")\n    assert False, "Malo zlyhat"\nexcept ValueError:\n    pass', 'is_hidden': True}]}]

