COMPANIONS[(4, 1)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Generátor násobkov čísla', 'title_en': 'Exercise 2 (Medium): Multiples Generator', 'instructions_sk': 'Napíš funkciu `vygeneruj_nasobky(zaklad, pocet=5)`: vráti zoznam prvých `pocet` kladných násobkov čísla `zaklad`.', 'instructions_en': 'Write `vygeneruj_nasobky(zaklad, pocet=5)` returning list of first multiples.', 'starter_code': 'def vygeneruj_nasobky(zaklad, pocet=5):\n    pass\n', 'solution_code': 'def vygeneruj_nasobky(zaklad, pocet=5):\n    return [zaklad * i for i in range(1, pocet + 1)]\n', 'explanation_sk': 'Použitie range(1, pocet + 1) na generovanie násobkov.', 'explanation_en': 'List comprehension generating multiples via range().', 'hint_sk': 'return [zaklad * i for i in range(1, pocet + 1)]', 'hint_en': 'Use range(1, pocet + 1).', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'vygeneruj_nasobky(5, 3)', 'expected_output': '[5, 10, 15]', 'test_code': 'assert vygeneruj_nasobky(5, 3) == [5, 10, 15]', 'is_hidden': False}, {'input_data': 'vygeneruj_nasobky(7, 2)', 'expected_output': '[7, 14]', 'test_code': 'assert vygeneruj_nasobky(7, 2) == [7, 14]', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Prvých N členov Fibonacciho postupnosti', 'title_en': 'Exercise 3 (Boss Challenge): Fibonacci Sequence Generator', 'instructions_sk': 'Napíš funkciu `fibonacci(n)`: vráti zoznam prvých `n` členov Fibonacciho postupnosti začínajúcej `[0, 1]`. Pre $n=1$ vráti `[0]`, pre $n \\le 0$ vráti prázdny zoznam `[]`.', 'instructions_en': 'Write `fibonacci(n)` returning list of first n Fibonacci numbers.', 'starter_code': 'def fibonacci(n):\n    pass\n', 'solution_code': 'def fibonacci(n):\n    if n <= 0:\n        return []\n    if n == 1:\n        return [0]\n    seq = [0, 1]\n    while len(seq) < n:\n        seq.append(seq[-1] + seq[-2])\n    return seq\n', 'explanation_sk': 'Generovanie postupnosti akumuláciou dvoch predchádzajúcich hodnôt.', 'explanation_en': 'Iterative Fibonacci sequence assembly.', 'hint_sk': 'Začni s [0, 1] a v cykle pridávaj seq[-1] + seq[-2].', 'hint_en': 'Append sum of last two elements in loop.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'fibonacci(6)', 'expected_output': '[0, 1, 1, 2, 3, 5]', 'test_code': 'assert fibonacci(6) == [0, 1, 1, 2, 3, 5]', 'is_hidden': False}, {'input_data': 'fibonacci(1)', 'expected_output': '[0]', 'test_code': 'assert fibonacci(1) == [0]', 'is_hidden': False}, {'input_data': 'fibonacci(0)', 'expected_output': '[]', 'test_code': 'assert fibonacci(0) == []', 'is_hidden': True}]}]

