COMPANIONS[(4, 2)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Nájdenie druhého najväčšieho čísla', 'title_en': 'Exercise 2 (Medium): Second Largest Unique Number', 'instructions_sk': 'Napíš funkciu `druhe_maximum(cisla)`: vráti druhé najväčšie unikátne číslo zo zoznamu. Ak má zoznam menej ako 2 rôzne čísla, vráti `None`.', 'instructions_en': 'Write `druhe_maximum(cisla)` returning second largest unique value or None.', 'starter_code': 'def druhe_maximum(cisla):\n    pass\n', 'solution_code': 'def druhe_maximum(cisla):\n    unikatne = sorted(set(cisla))\n    if len(unikatne) < 2:\n        return None\n    return unikatne[-2]\n', 'explanation_sk': 'Použitie set() na odstránenie duplikátov a triedenie.', 'explanation_en': 'Set deduplication and indexing second to last element.', 'hint_sk': 'u = sorted(set(cisla)); return u[-2] if len(u) >= 2 else None', 'hint_en': 'Use set and sorted.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'druhe_maximum([10, 20, 4, 45, 99, 99])', 'expected_output': '45', 'test_code': 'assert druhe_maximum([10, 20, 4, 45, 99, 99]) == 45', 'is_hidden': False}, {'input_data': 'druhe_maximum([5, 5, 5])', 'expected_output': 'None', 'test_code': 'assert druhe_maximum([5, 5, 5]) is None', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Priebežné kumulatívne súčty', 'title_en': 'Exercise 3 (Boss Challenge): Cumulative Sum Stream', 'instructions_sk': 'Napíš funkciu `kumulativne_sucty(cisla)`: vráti nový zoznam, kde každý prvok je súčtom všetkých predchádzajúcich prvkov vrátane aktuálneho.', 'instructions_en': 'Write `kumulativne_sucty(cisla)` returning running cumulative sum list.', 'starter_code': 'def kumulativne_sucty(cisla):\n    pass\n', 'solution_code': 'def kumulativne_sucty(cisla):\n    vysledok = []\n    beziaci = 0\n    for x in cisla:\n        beziaci += x\n        vysledok.append(beziaci)\n    return vysledok\n', 'explanation_sk': 'Priebežná akumulácia v cykle.', 'explanation_en': 'Prefix sum iterative accumulator.', 'hint_sk': 'beziaci += x; vysledok.append(beziaci)', 'hint_en': 'Keep running sum in loop.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'kumulativne_sucty([1, 2, 3, 4])', 'expected_output': '[1, 3, 6, 10]', 'test_code': 'assert kumulativne_sucty([1, 2, 3, 4]) == [1, 3, 6, 10]', 'is_hidden': False}, {'input_data': 'kumulativne_sucty([])', 'expected_output': '[]', 'test_code': 'assert kumulativne_sucty([]) == []', 'is_hidden': True}]}]

