COMPANIONS[(4, 3)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Počet cifier čísla cyklom while', 'title_en': 'Exercise 1 (Easy): Count Digits with While Loop', 'instructions_sk': 'Napíš funkciu `pocet_cifier(cislo)`: pomocou celočíselného delenia `// 10` v cykle `while` spočíta počet cifier nezáporného čísla. Pre 0 vráti 1.', 'instructions_en': 'Write `pocet_cifier(cislo)` counting digits with while loop.', 'starter_code': 'def pocet_cifier(cislo):\n    pass\n', 'solution_code': 'def pocet_cifier(cislo):\n    cislo = abs(cislo)\n    if cislo == 0:\n        return 1\n    pocet = 0\n    while cislo > 0:\n        pocet += 1\n        cislo //= 10\n    return pocet\n', 'explanation_sk': 'Celočíselné skracovanie čísla deliteľom 10 v cykle while.', 'explanation_en': 'Integer division by 10 in while loop.', 'hint_sk': 'while cislo > 0: pocet += 1; cislo //= 10', 'hint_en': 'Divide by 10 until 0.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'pocet_cifier(12345)', 'expected_output': '5', 'test_code': 'assert pocet_cifier(12345) == 5', 'is_hidden': False}, {'input_data': 'pocet_cifier(0)', 'expected_output': '1', 'test_code': 'assert pocet_cifier(0) == 1', 'is_hidden': False}, {'input_data': 'pocet_cifier(9)', 'expected_output': '1', 'test_code': 'assert pocet_cifier(9) == 1', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Collatzova postupnosť (3n + 1)', 'title_en': 'Exercise 3 (Boss Challenge): Collatz 3n+1 Sequence', 'instructions_sk': 'Napíš funkciu `collatz_dlzka(n)`: pre kladné celé číslo $n$ počíta kroky pravidla: ak je $n$ párne, $n = n // 2$, inak $n = 3n + 1$. Zastaví sa, keď $n == 1$. Funkcia vráti celkový počet vykonaných krokov (pre 1 vráti 0).', 'instructions_en': 'Write `collatz_dlzka(n)` returning step count reaching 1.', 'starter_code': 'def collatz_dlzka(n):\n    pass\n', 'solution_code': 'def collatz_dlzka(n):\n    kroky = 0\n    while n > 1:\n        if n % 2 == 0:\n            n //= 2\n        else:\n            n = 3 * n + 1\n        kroky += 1\n    return kroky\n', 'explanation_sk': 'Simulácia Collatzovho problému s podmieneným while cyklom.', 'explanation_en': 'Collatz conjecture step counter simulation.', 'hint_sk': 'while n > 1: n = n // 2 if n % 2 == 0 else 3*n + 1; kroky += 1', 'hint_en': 'Loop while n > 1 tracking steps.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'collatz_dlzka(6)', 'expected_output': '8', 'test_code': 'assert collatz_dlzka(6) == 8', 'is_hidden': False}, {'input_data': 'collatz_dlzka(1)', 'expected_output': '0', 'test_code': 'assert collatz_dlzka(1) == 0', 'is_hidden': True}]}]

