COMPANIONS[(4, 4)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Hľadanie prvého záporného čísla', 'title_en': 'Exercise 1 (Easy): Find First Negative Number Index', 'instructions_sk': 'Napíš funkciu `prvy_zaporny(cisla)`: vráti index prvého záporného čísla v zozname (s okamžitým `break`). Ak sa v zozname záporné číslo nenachádza, vráti `-1`.', 'instructions_en': 'Write `prvy_zaporny(cisla)` returning index of first negative number or -1.', 'starter_code': 'def prvy_zaporny(cisla):\n    pass\n', 'solution_code': 'def prvy_zaporny(cisla):\n    for i, x in enumerate(cisla):\n        if x < 0:\n            return i\n    return -1\n', 'explanation_sk': 'Predčasné ukončenie prehľadávania pri nájdení prvého zhody.', 'explanation_en': 'Early return upon encountering first negative match.', 'hint_sk': 'for i, x in enumerate(cisla): if x < 0: return i. Na konci return -1.', 'hint_en': 'Use enumerate and return index.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'prvy_zaporny([5, 8, -3, 10])', 'expected_output': '2', 'test_code': 'assert prvy_zaporny([5, 8, -3, 10]) == 2', 'is_hidden': False}, {'input_data': 'prvy_zaporny([1, 2, 3])', 'expected_output': '-1', 'test_code': 'assert prvy_zaporny([1, 2, 3]) == -1', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Nájdenie všetkých deliteľov čísla', 'title_en': 'Exercise 3 (Boss Challenge): Find All Divisors', 'instructions_sk': 'Napíš funkciu `najdi_delitele(n)`: vráti zoradený zoznam všetkých kladných celočíselných deliteľov čísla `n`.', 'instructions_en': 'Write `najdi_delitele(n)` returning sorted list of positive divisors.', 'starter_code': 'def najdi_delitele(n):\n    pass\n', 'solution_code': 'def najdi_delitele(n):\n    if n <= 0:\n        return []\n    delitele = []\n    for i in range(1, int(n**0.5) + 1):\n        if n % i == 0:\n            delitele.append(i)\n            if i != n // i:\n                delitele.append(n // i)\n    return sorted(delitele)\n', 'explanation_sk': 'Efektívne hľadanie deliteľov do odmocniny n.', 'explanation_en': 'Efficient divisor discovery up to square root of n.', 'hint_sk': 'Prechádzaj do odmocniny z n a pridávaj i aj n // i.', 'hint_en': 'Iterate up to sqrt(n) adding pairs.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'najdi_delitele(12)', 'expected_output': '[1, 2, 3, 4, 6, 12]', 'test_code': 'assert najdi_delitele(12) == [1, 2, 3, 4, 6, 12]', 'is_hidden': False}, {'input_data': 'najdi_delitele(7)', 'expected_output': '[1, 7]', 'test_code': 'assert najdi_delitele(7) == [1, 7]', 'is_hidden': True}]}]

