COMPANIONS[(4, 5)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Kreslenie obdĺžnika znakmi', 'title_en': 'Exercise 1 (Easy): Draw Character Rectangle', 'instructions_sk': 'Napíš funkciu `kresli_obdlznik(sirka, vyska, znak="#")`: vráti viacriadkový reťazec reprezentujúci plný obdĺžnik znakov danej šírky a výšky oddelený `\\n`.', 'instructions_en': 'Write `kresli_obdlznik(sirka, vyska, znak="#")` returning multiline string.', 'starter_code': 'def kresli_obdlznik(sirka, vyska, znak="#"):\n    pass\n', 'solution_code': 'def kresli_obdlznik(sirka, vyska, znak="#"):\n    riadok = znak * sirka\n    return "\\n".join([riadok for _ in range(vyska)])\n', 'explanation_sk': 'Viacriadkové spojenie reťazcov pomocou join a násobenia.', 'explanation_en': 'Multiline assembly of repeated rows.', 'hint_sk': '"\\n".join([znak * sirka for _ in range(vyska)])', 'hint_en': 'Join repeated rows with newline.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'kresli_obdlznik(4, 2, "*")', 'expected_output': '****\\n****', 'test_code': 'assert kresli_obdlznik(4, 2, "*") == "****\\n****"', 'is_hidden': False}]}, {'order': 2, 'title_sk': 'Úloha 2 (Stredná): Tabuľka malej násobilky ako 2D matica', 'title_en': 'Exercise 2 (Medium): 2D Multiplication Table Grid', 'instructions_sk': 'Napíš funkciu `tabulka_nasobilky(n)`: vráti 2D zoznam rozmerov $n \\times n$, kde prvok na pozícii `[r][c]` má hodnotu `(r + 1) * (c + 1)`.', 'instructions_en': 'Write `tabulka_nasobilky(n)` returning 2D n x n multiplication table.', 'starter_code': 'def tabulka_nasobilky(n):\n    pass\n', 'solution_code': 'def tabulka_nasobilky(n):\n    return [[(r + 1) * (c + 1) for c in range(n)] for r in range(n)]\n', 'explanation_sk': 'Vnorené generovanie 2D zoznamu cez List Comprehension.', 'explanation_en': 'Nested list comprehension generating 2D multiplication table.', 'hint_sk': '[[(r+1)*(c+1) for c in range(n)] for r in range(n)]', 'hint_en': 'Use nested list comprehension.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'tabulka_nasobilky(3)', 'expected_output': '[[1, 2, 3], [2, 4, 6], [3, 6, 9]]', 'test_code': 'assert tabulka_nasobilky(3) == [[1, 2, 3], [2, 4, 6], [3, 6, 9]]', 'is_hidden': False}]}]

