COMPANIONS[(5, 1)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Prevod teploty medzi Celsius a Fahrenheit', 'title_en': 'Exercise 2 (Medium): Temperature Conversion', 'instructions_sk': 'Napíš funkciu `celsius_na_fahrenheit(celsius)`: vráti zaokrúhlenú hodnotu $F = C \\times \\frac{9}{5} + 32$ na 2 desatinné miesta.', 'instructions_en': 'Write `celsius_na_fahrenheit(celsius)` returning converted float.', 'starter_code': 'def celsius_na_fahrenheit(celsius):\n    pass\n', 'solution_code': 'def celsius_na_fahrenheit(celsius):\n    return round(celsius * (9.0 / 5.0) + 32, 2)\n', 'explanation_sk': 'Aritmetický prepočet teploty so zaokrúhlením.', 'explanation_en': 'Temperature conversion formula with rounding.', 'hint_sk': 'return round(celsius * (9.0 / 5.0) + 32, 2)', 'hint_en': 'Use conversion formula.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'celsius_na_fahrenheit(0)', 'expected_output': '32.0', 'test_code': 'assert celsius_na_fahrenheit(0) == 32.0', 'is_hidden': False}, {'input_data': 'celsius_na_fahrenheit(100)', 'expected_output': '212.0', 'test_code': 'assert celsius_na_fahrenheit(100) == 212.0', 'is_hidden': False}, {'input_data': 'celsius_na_fahrenheit(25)', 'expected_output': '77.0', 'test_code': 'assert celsius_na_fahrenheit(25) == 77.0', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Riešenie kvadratickej rovnice', 'title_en': 'Exercise 3 (Boss Challenge): Quadratic Equation Solver', 'instructions_sk': 'Napíš funkciu `ries_kvadraticku(a, b, c)`: vráti zoradené korene rovnice $ax^2 + bx + c = 0$ ako n-ticu `()`, `(koren,)` alebo `(koren1, koren2)`.', 'instructions_en': 'Write `ries_kvadraticku(a, b, c)` returning tuple of roots.', 'starter_code': 'def ries_kvadraticku(a, b, c):\n    pass\n', 'solution_code': 'def ries_kvadraticku(a, b, c):\n    d = b**2 - 4 * a * c\n    if d < 0:\n        return ()\n    elif d == 0:\n        x = -b / (2 * a)\n        return (round(x, 2),)\n    else:\n        x1 = (-b - d**0.5) / (2 * a)\n        x2 = (-b + d**0.5) / (2 * a)\n        korene = sorted([round(x1, 2), round(x2, 2)])\n        return (korene[0], korene[1])\n', 'explanation_sk': 'Výpočet diskriminantu a koreňov kvadratickej rovnice.', 'explanation_en': 'Quadratic discriminant solver returning root tuple.', 'hint_sk': 'd = b**2 - 4*a*c; x1 = (-b - d**0.5)/(2*a)', 'hint_en': 'Compute D and roots.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'ries_kvadraticku(1, -5, 6)', 'expected_output': '(2.0, 3.0)', 'test_code': 'assert ries_kvadraticku(1, -5, 6) == (2.0, 3.0)', 'is_hidden': False}, {'input_data': 'ries_kvadraticku(1, -2, 1)', 'expected_output': '(1.0,)', 'test_code': 'assert ries_kvadraticku(1, -2, 1) == (1.0,)', 'is_hidden': False}, {'input_data': 'ries_kvadraticku(1, 0, 1)', 'expected_output': '()', 'test_code': 'assert ries_kvadraticku(1, 0, 1) == ()', 'is_hidden': True}]}]

