COMPANIONS[(5, 3)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Bezpečná čistá funkcia (Pure Function)', 'title_en': 'Exercise 1 (Easy): Pure Double Function', 'instructions_sk': 'Napíš funkciu `zdvojnasob_prvky(zoznam)`: vráti nový zoznam, kde je každé číslo vynásobené 2 bez zmeny pôvodného zoznamu.', 'instructions_en': 'Write `zdvojnasob_prvky(zoznam)` returning new list with doubled elements without mutating input.', 'starter_code': 'def zdvojnasob_prvky(zoznam):\n    pass\n', 'solution_code': 'def zdvojnasob_prvky(zoznam):\n    return [x * 2 for x in zoznam]\n', 'explanation_sk': 'Čistá funkcia bez vedľajších účinkov.', 'explanation_en': 'Pure function creating a new list without side effects.', 'hint_sk': 'return [x * 2 for x in zoznam]', 'hint_en': 'Return new list comprehension.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'a = [1, 2, 3]; b = zdvojnasob_prvky(a)', 'expected_output': '[2, 4, 6]', 'test_code': 'a = [1, 2, 3]\nb = zdvojnasob_prvky(a)\nassert b == [2, 4, 6]\nassert a == [1, 2, 3]', 'is_hidden': False}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Uzáver (Closure) s vnútorným počítadlom', 'title_en': 'Exercise 3 (Boss Challenge): Counter Closure Function', 'instructions_sk': 'Napíš funkciu `vytvor_pocitadlo(start=0)`: vráti vnútornú funkciu (uzáver / closure), ktorá pri každom zavolaní vráti aktuálnu hodnotu a zvýši ju o 1.', 'instructions_en': 'Write `vytvor_pocitadlo(start=0)` returning incrementing closure function.', 'starter_code': 'def vytvor_pocitadlo(start=0):\n    pass\n', 'solution_code': 'def vytvor_pocitadlo(start=0):\n    stav = [start]\n    def pocitaj():\n        val = stav[0]\n        stav[0] += 1\n        return val\n    return pocitaj\n', 'explanation_sk': 'Použitie uzáveru na zapuzdrenie stavu premennej.', 'explanation_en': 'Closure capturing mutable state across successive invocations.', 'hint_sk': 'Definuj stav = [start] a vnútri vráť val = stav[0]; stav[0] += 1.', 'hint_en': 'Use closure state list and return inner function.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'p = vytvor_pocitadlo(10); p(); p()', 'expected_output': '11', 'test_code': 'p = vytvor_pocitadlo(10)\nassert p() == 10\nassert p() == 11\nassert p() == 12', 'is_hidden': False}]}]

