COMPANIONS[(5, 4)] = [{'order': 2, 'title_sk': 'Úloha 2 (Stredná): Filtrovanie zoznamu cez lambda výraz', 'title_en': 'Exercise 2 (Medium): Filter with Lambda Expression', 'instructions_sk': 'Napíš funkciu `filtruj_dlhe_slova(slova, min_dlzka=5)`: použije vstavanú funkciu `filter()` a `lambda` výraz, aby vrátila zoznam slov s dĺžkou aspoň `min_dlzka`.', 'instructions_en': 'Write `filtruj_dlhe_slova(slova, min_dlzka=5)` using filter() and lambda.', 'starter_code': 'def filtruj_dlhe_slova(slova, min_dlzka=5):\n    pass\n', 'solution_code': 'def filtruj_dlhe_slova(slova, min_dlzka=5):\n    return list(filter(lambda s: len(s) >= min_dlzka, slova))\n', 'explanation_sk': 'Kombinácia filter() a anonymnej lambda funkcie.', 'explanation_en': 'Using filter() with anonymous lambda predicate.', 'hint_sk': 'list(filter(lambda s: len(s) >= min_dlzka, slova))', 'hint_en': 'Use filter with lambda.', 'hint_cost_doros': 10, 'difficulty': 'MEDIUM', 'xp_reward': 45, 'doros_reward': 20, 'test_cases': [{'input_data': 'filtruj_dlhe_slova(["pes", "programovanie", "kod", "python"])', 'expected_output': '["programovanie", "python"]', 'test_code': 'assert filtruj_dlhe_slova(["pes", "programovanie", "kod", "python"]) == ["programovanie", "python"]', 'is_hidden': False}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Zlúčenie konfigurácií cez **kwargs', 'title_en': 'Exercise 3 (Boss Challenge): Deep Configuration Merge with **kwargs', 'instructions_sk': 'Napíš funkciu `zluc_konfiguracie(*slovniky, **prepisy)`: postupne zlúči všetky pozičné slovníky do jedného nového slovníka a prepíše hodnoty kľúčmi z `prepisy`.', 'instructions_en': 'Write `zluc_konfiguracie(*slovniky, **prepisy)` merging dictionaries with overrides.', 'starter_code': 'def zluc_konfiguracie(*slovniky, **prepisy):\n    pass\n', 'solution_code': 'def zluc_konfiguracie(*slovniky, **prepisy):\n    vysledok = {}\n    for d in slovniky:\n        vysledok.update(d)\n    vysledok.update(prepisy)\n    return vysledok\n', 'explanation_sk': 'Použitie *args a **kwargs pre variabilné vstupy.', 'explanation_en': 'Dictionary aggregation combining variable positional and keyword arguments.', 'hint_sk': 'for d in slovniky: vysledok.update(d); vysledok.update(prepisy)', 'hint_en': 'Loop over dictionaries and update.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'zluc_konfiguracie({"a": 1, "b": 2}, {"b": 3, "c": 4}, c=99, d=100)', 'expected_output': '{"a": 1, "b": 3, "c": 99, "d": 100}', 'test_code': 'assert zluc_konfiguracie({"a": 1, "b": 2}, {"b": 3, "c": 4}, c=99, d=100) == {"a": 1, "b": 3, "c": 99, "d": 100}', 'is_hidden': False}]}]

