COMPANIONS[(7, 5)] = [{'order': 1, 'title_sk': 'Úloha 1 (Ľahká): Nájdenie najčastejšieho písmena', 'title_en': 'Exercise 1 (Easy): Most Frequent Letter', 'instructions_sk': 'Napíš funkciu `najcastejsie_pismeno(text)`: vráti najčastejšie malé písmeno.', 'instructions_en': 'Write `najcastejsie_pismeno(text)` returning most frequent lowercase letter.', 'starter_code': 'def najcastejsie_pismeno(text):\n    pass\n', 'solution_code': 'def najcastejsie_pismeno(text):\n    frekvencia = {}\n    for c in text.lower():\n        if c.isalpha():\n            frekvencia[c] = frekvencia.get(c, 0) + 1\n    if not frekvencia:\n        return ""\n    return max(frekvencia, key=frekvencia.get)\n', 'explanation_sk': 'Frekvenčná analýza znakov.', 'explanation_en': 'Character frequency counting extracting max value key.', 'hint_sk': 'max(frekvencia, key=frekvencia.get)', 'hint_en': 'Find key with max frequency.', 'hint_cost_doros': 5, 'difficulty': 'EASY', 'xp_reward': 25, 'doros_reward': 10, 'test_cases': [{'input_data': 'najcastejsie_pismeno("Bratislava")', 'expected_output': 'a', 'test_code': 'assert najcastejsie_pismeno("Bratislava") == "a"', 'is_hidden': False}, {'input_data': 'najcastejsie_pismeno("123---")', 'expected_output': '', 'test_code': 'assert najcastejsie_pismeno("123---") == ""', 'is_hidden': True}]}, {'order': 3, 'title_sk': 'Úloha 3 (Boss Výzva): Top K najčastejších slov v texte', 'title_en': 'Exercise 3 (Boss Challenge): Top K Most Frequent Words', 'instructions_sk': 'Napíš funkciu `top_k_slov(text, k=2)`: vráti zoznam `k` najčastejších slov.', 'instructions_en': 'Write `top_k_slov(text, k=2)` returning list of top k words.', 'starter_code': 'def top_k_slov(text, k=2):\n    pass\n', 'solution_code': 'def top_k_slov(text, k=2):\n    slova = [w.strip(".,!?:;").lower() for w in text.split() if w.strip(".,!?:;")]\n    pocitadla = {}\n    for w in slova:\n        pocitadla[w] = pocitadla.get(w, 0) + 1\n    zoradene = sorted(pocitadla.keys(), key=lambda w: pocitadla[w], reverse=True)\n    return zoradene[:k]\n', 'explanation_sk': 'Zoradenie slov podľa frekvencie a orezanie.', 'explanation_en': 'Word token frequency ranking and top k slicing.', 'hint_sk': 'sorted(pocitadla.keys(), key=lambda w: pocitadla[w], reverse=True)[:k]', 'hint_en': 'Sort keys by frequency descending.', 'hint_cost_doros': 15, 'difficulty': 'HARD', 'xp_reward': 75, 'doros_reward': 35, 'test_cases': [{'input_data': 'top_k_slov("jablko hruska jablko banan jablko hruska", 2)', 'expected_output': '["jablko", "hruska"]', 'test_code': 'assert top_k_slov("jablko hruska jablko banan jablko hruska", 2) == ["jablko", "hruska"]', 'is_hidden': False}]}]

